import { StringEnum, completeSimple, isContextOverflow } from "@earendil-works/pi-ai";
import type { ExtensionAPI, ExtensionContext } from "@earendil-works/pi-coding-agent";
import { getMarkdownTheme } from "@earendil-works/pi-coding-agent";
import { Markdown, matchesKey, truncateToWidth } from "@earendil-works/pi-tui";
import { Type } from "typebox";
import {
	MEMORY_COMPACTION_INSTRUCTIONS,
	addTodoItem,
	applyMemoryCompactionCheckpoint,
	canWriteSessionMemory,
	createActiveTodo,
	createDream,
	createDreamIfStale,
	formatDreamStatus,
	loadMemoryState,
	memoryPacket,
	memoryWritesDisabledMessage,
	migrateLegacyMemoryLayout,
	parseMemoryCompactionCheckpoint,
	refreshProgressDashboard,
	updateTodoStatus,
	writeCheckpoint,
	writeCompactionCheckpoint,
	type MemoryCompactionCheckpoint,
	type MemoryState,
	type MemoryWriteResult,
} from "./memory.ts";
import { createMemoryDigest, formatMemoryDigestStatus, getMemoryDigestStatus } from "./memory-digest.ts";
import { formatMemoryLintReport, lintMemory } from "./memory-lint.ts";
import { MEMORY_RECALL_SCOPES, expandMemorySource, formatMemoryRecall, recallMemory } from "./memory-recall.ts";
import { MemoryTodoWidget } from "./todo-widget.ts";

let lastInjectedProject = "";
const pendingCompactions = new Map<string, PendingCompaction>();
let autoContinueMode: AutoContinueMode = "on";
let lastAutoContinuedCompactionId = "";
let suppressAutoContinueUntil = 0;
let footerStatusEnabled = false;
const memoryTodoWidget = new MemoryTodoWidget();

const AUTO_CONTINUE_SETTINGS_TYPE = "pi-memory-workbench-autocontinue-settings";
const AUTO_CONTINUE_RECORD_TYPE = "pi-memory-workbench-autocontinue-record";
const FOOTER_STATUS_SETTINGS_TYPE = "pi-memory-workbench-footer-status-settings";
const OVERFLOW_RECOVERY_SUPPRESS_MS = 5000;

type AutoContinueMode = "off" | "on";

type PendingCompaction = {
	sessionId: string;
	current: MemoryState;
	branchEntries: CheckpointEntry[];
	signal: AbortSignal;
	skipAutoContinue: boolean;
	skipCheckpointWrites: boolean;
};

type CheckpointEntry = {
	id?: string;
	type?: string;
	role?: unknown;
	stopReason?: unknown;
	errorMessage?: unknown;
	usage?: unknown;
	message?: unknown;
	customType?: unknown;
	content?: unknown;
	summary?: unknown;
	details?: unknown;
	data?: unknown;
};

async function refresh(ctx: ExtensionContext): Promise<MemoryState> {
	const current = await loadMemoryState(ctx);
	if (ctx.hasUI) {
		if (footerStatusEnabled) {
			memoryTodoWidget.update(ctx, current);
			ctx.ui.setStatus("pi-memory", `memory: ${current.parsedTodo ? "todo" : "ready"} | dream: ${formatDreamStatus(current.dream)}`);
		} else {
			memoryTodoWidget.clear(ctx);
			ctx.ui.setStatus("pi-memory", undefined);
		}
	}
	return current;
}

async function refreshForWrite(ctx: ExtensionContext): Promise<MemoryState> {
	const initial = await refresh(ctx);
	assertMemoryWritesEnabled(initial);
	await migrateLegacyMemoryLayout(ctx);
	const current = await refresh(ctx);
	assertMemoryWritesEnabled(current);
	return current;
}

async function refreshForExplicitWrite(ctx: ExtensionContext): Promise<MemoryState> {
	const current = await refresh(ctx);
	assertMemoryWritesEnabled(current);
	return current;
}

function assertMemoryWritesEnabled(state: MemoryState, action?: string): void {
	if (!canWriteSessionMemory(state)) throw new Error(memoryWritesDisabledMessage(state, action));
}

function show(pi: ExtensionAPI, ctx: ExtensionContext, message: string): void {
	if (ctx.hasUI) ctx.ui.notify(message, "info");
	else {
		console.log(message);
		pi.sendMessage({ customType: "pi-memory-workbench", content: message, display: true }, { deliverAs: "nextTurn" });
	}
}

function restoreSessionState(ctx: ExtensionContext): void {
	autoContinueMode = "on";
	lastAutoContinuedCompactionId = "";
	footerStatusEnabled = false;
	for (const entry of ctx.sessionManager.getEntries()) {
		if (entry.type !== "custom") continue;
		const data = (entry as CheckpointEntry).data;
		if (entry.customType === AUTO_CONTINUE_SETTINGS_TYPE && data && typeof data === "object" && !Array.isArray(data)) {
			const mode = (data as { mode?: unknown }).mode;
			if (mode === "off") autoContinueMode = "off";
			if (mode === "on" || mode === "auto" || mode === "always") autoContinueMode = "on";
		}
		if (entry.customType === AUTO_CONTINUE_RECORD_TYPE && data && typeof data === "object" && !Array.isArray(data)) {
			const compactionId = (data as { compactionId?: unknown }).compactionId;
			if (typeof compactionId === "string") lastAutoContinuedCompactionId = compactionId;
		}
		if (entry.customType === FOOTER_STATUS_SETTINGS_TYPE && data && typeof data === "object" && !Array.isArray(data)) {
			const enabled = (data as { enabled?: unknown }).enabled;
			if (enabled === true) footerStatusEnabled = true;
			if (enabled === false) footerStatusEnabled = false;
		}
	}
}

function autoContinueModeFromCommand(value: string): AutoContinueMode | undefined {
	if (value === "off") return "off";
	if (value === "on" || value === "auto" || value === "always") return "on";
	return undefined;
}

function isLikelyOverflowRecoveryEnding(messages: CheckpointEntry[], contextWindow?: number): boolean {
	let lastAssistant: CheckpointEntry | undefined;
	for (let index = messages.length - 1; index >= 0; index--) {
		if (messages[index].role === "assistant") {
			lastAssistant = messages[index];
			break;
		}
	}
	if (!lastAssistant) return false;

	const usage = lastAssistant.usage;
	const input = usage && typeof usage === "object" && !Array.isArray(usage) && typeof (usage as { input?: unknown }).input === "number" ? (usage as { input: number }).input : 0;
	const cacheRead = usage && typeof usage === "object" && !Array.isArray(usage) && typeof (usage as { cacheRead?: unknown }).cacheRead === "number" ? (usage as { cacheRead: number }).cacheRead : 0;
	const output = usage && typeof usage === "object" && !Array.isArray(usage) && typeof (usage as { output?: unknown }).output === "number" ? (usage as { output: number }).output : 0;
	const stopReason = typeof lastAssistant.stopReason === "string" ? lastAssistant.stopReason : "";
	return isContextOverflow({
		role: "assistant",
		content: [],
		usage: {
			input,
			cacheRead,
			output,
			cacheWrite: 0,
			totalTokens: input + cacheRead + output,
			cost: { input: 0, cacheRead: 0, output: 0, cacheWrite: 0, total: 0 },
		},
		stopReason,
		errorMessage: typeof lastAssistant.errorMessage === "string" ? lastAssistant.errorMessage : undefined,
		timestamp: Date.now(),
	} as unknown as Parameters<typeof isContextOverflow>[0], contextWindow);
}

function autoContinueContent(current: MemoryState, eventPath?: string): string {
	const activeTodo = current.activeTodoPath ?? current.paths.sessionTodoPath;
	return `${memoryPacket(current)}

The previous turn was interrupted by native Pi compaction. Continue the prior task from refreshed session memory:
- Read this session's progress: ${current.paths.sessionProgressPath}.
- Read this session's todo if it exists: ${activeTodo}.
${eventPath ? `- Read the latest compaction event: ${eventPath}.` : "- Review recent events listed in the memory packet if needed."}
- Shared ${current.paths.progressPath} is only a dashboard, not the source of continuity.
- Use the session Resume Here state and session todo as the source of continuity.
- Do not summarize compaction. Continue the next action if it is clear.
- Ask the user only if genuinely blocked or the memory/source files leave the next step ambiguous.`;
}

function autoContinueStatus(): string {
	const last = `Last continued compaction: ${lastAutoContinuedCompactionId || "none"}.`;
	if (autoContinueMode === "off") return `Memory auto-continue: off. Default is on; use /memory-autocontinue on to re-enable it. Legacy aliases auto and always are accepted as on. ${last}`;
	return `Memory auto-continue: on. Hidden follow-up turns run after non-aborted, non-boomerang compactions. Likely Pi overflow-recovery compactions are suppressed. Use /memory-autocontinue off to disable it. ${last}`;
}

function footerStatusMessage(): string {
	return `Memory editor/footer chrome: ${footerStatusEnabled ? "on" : "off"}. Default is off; use /memory-footer on to show the markdown todo widget and compact pi-memory footer status.`;
}

async function maybeAutoContinueAfterCompaction(pi: ExtensionAPI, current: MemoryState, compactionId: string, writeResult: MemoryWriteResult | undefined, checkpointAborted: boolean, skip: boolean): Promise<void> {
	if (autoContinueMode === "off" || checkpointAborted || skip || !writeResult?.progressUpdated || !compactionId || lastAutoContinuedCompactionId === compactionId) return;

	lastAutoContinuedCompactionId = compactionId;
	pi.appendEntry(AUTO_CONTINUE_RECORD_TYPE, { compactionId, sessionId: current.session.id, mode: autoContinueMode, timestamp: new Date().toISOString() });
	pi.sendMessage(
		{ customType: "pi-memory-workbench-autocontinue", content: autoContinueContent(current, writeResult.eventPath), display: false, details: { compactionId, sessionId: current.session.id, mode: autoContinueMode } },
		{ triggerTurn: true, deliverAs: "followUp" },
	);
}

async function showTodoOverlay(ctx: ExtensionContext, current: MemoryState): Promise<void> {
	if (!ctx.hasUI) {
		console.log(memoryPacket(current));
		return;
	}
	const markdown = current.activeTodo ?? "No active todo. Use `/todo-new <title>` to create one.";
	await ctx.ui.custom<void>((_tui, theme, _keybindings, done) => {
		const rendered = new Markdown(markdown, 1, 1, getMarkdownTheme());
		return {
			render(width: number) {
				const title = theme.fg("accent", " pi-memory-workbench todo ");
				const border = theme.fg("borderMuted", "─".repeat(Math.max(0, width - 1)));
				return [truncateToWidth(title + border, width), ...rendered.render(width), theme.fg("dim", "Esc closes")];
			},
			invalidate() {
				rendered.invalidate();
			},
			handleInput(data: string) {
				if (matchesKey(data, "escape") || matchesKey(data, "ctrl+c")) done();
			},
		};
	}, { overlay: true, overlayOptions: { width: "80%", maxHeight: "80%" } });
}

async function generateMemoryCheckpoint(params: {
	current: MemoryState;
	summary: string;
	branchEntries: CheckpointEntry[];
	firstKeptEntryId: string;
	model: NonNullable<ExtensionContext["model"]>;
	apiKey: string;
	headers?: Record<string, string>;
	thinkingLevel: ReturnType<ExtensionAPI["getThinkingLevel"]>;
	notableActivity: string;
	signal?: AbortSignal;
}): Promise<MemoryCompactionCheckpoint> {
	const prompt = `${MEMORY_COMPACTION_INSTRUCTIONS}

<memory-packet>
${memoryPacket(params.current)}
</memory-packet>

<normal-compaction-summary>
${params.summary}
</normal-compaction-summary>

<notable-activity>
${params.notableActivity}
</notable-activity>

<retained-recent-context>
${retainedContextForCheckpoint(params.branchEntries, params.firstKeptEntryId)}
</retained-recent-context>`;
	if (params.signal?.aborted) throw new Error("Memory checkpoint generation aborted");
	const options = { maxTokens: 2048, signal: params.signal, apiKey: params.apiKey, headers: params.headers };
	const response = await completeSimple(
		params.model,
		{ systemPrompt: "You write parseable memory checkpoint XML only. Do not continue the conversation.", messages: [{ role: "user", content: [{ type: "text", text: prompt }], timestamp: Date.now() }] },
		params.model.reasoning && params.thinkingLevel !== "off" ? { ...options, reasoning: params.thinkingLevel } : options,
	);
	if (response.stopReason === "error") throw new Error(`Focused memory checkpoint generation failed: ${response.errorMessage || "Unknown error"}`);
	const text = response.content.filter((block): block is { type: "text"; text: string } => block.type === "text").map((block) => block.text).join("\n");
	try {
		return parseMemoryCompactionCheckpoint(text);
	} catch (error) {
		const reason = error instanceof Error ? error.message : String(error);
		throw new Error(`Focused memory checkpoint generation returned invalid XML: ${reason}`);
	}
}

function retainedContextForCheckpoint(branchEntries: CheckpointEntry[], firstKeptEntryId: string): string {
	const start = branchEntries.findIndex((entry) => entry.id === firstKeptEntryId);
	const rendered = (start >= 0 ? branchEntries.slice(start) : branchEntries.slice(-12)).map(entryForCheckpoint).filter(Boolean).join("\n\n");
	return rendered.length > 12000 ? `... [truncated]\n${rendered.slice(-12000)}` : rendered || "No retained context found.";
}

function entryForCheckpoint(entry: CheckpointEntry): string {
	if (entry.type === "message" && entry.message && typeof entry.message === "object") return messageForCheckpoint(entry.message as Record<string, unknown>);
	if (entry.type === "custom_message") {
		const text = textForCheckpoint(entry.content);
		return text ? `[custom:${String(entry.customType ?? "unknown")}]\n${text}` : "";
	}
	if (entry.type === "compaction" || entry.type === "branch_summary") {
		const text = textForCheckpoint(entry.summary);
		return text ? `[${entry.type}]\n${text}` : "";
	}
	return "";
}

function textForCheckpoint(value: unknown, max = 1200): string {
	const text = typeof value === "string" ? value : JSON.stringify(value) ?? "";
	return sanitizeCheckpointBlock(text, max);
}

function sanitizeCheckpointBlock(value: string, max: number): string {
	const text = redactSensitiveText(value).trim();
	if (!text || /^\(?no output\)?$/i.test(text)) return "";
	return text.length > max ? `${text.slice(0, max - 20).trimEnd()}\n... [truncated]` : text;
}

function redactSensitiveText(value: string): string {
	return value
		.replace(/\b((?:api[_-]?key|access[_-]?token|auth[_-]?token|bearer[_-]?token|refresh[_-]?token|secret|password|passwd|pwd)\b\s*[:=]\s*)([^\s'"`]+)/gi, "$1[REDACTED]")
		.replace(/\b(Bearer\s+)[A-Za-z0-9._~+\/-]+=*/gi, "$1[REDACTED]")
		.replace(/\b([A-Z][A-Z0-9_]*(?:TOKEN|SECRET|PASSWORD|PASSWD|API_KEY|PRIVATE_KEY)\b\s*=\s*)([^\s'"`]+)/g, "$1[REDACTED]")
		.replace(/-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----/g, "[REDACTED PRIVATE KEY]");
}

function messageForCheckpoint(message: Record<string, unknown>): string {
	const content = message.content;
	const role = String(message.role ?? "message");
	if (role === "toolResult" && message.isError === true) return "";
	if (typeof content === "string") {
		const text = textForCheckpoint(content);
		return text ? `[${role}]\n${text}` : "";
	}
	if (!Array.isArray(content)) return "";
	const blocks = content.map((block) => {
		if (!block || typeof block !== "object") return "";
		const value = block as Record<string, unknown>;
		if (value.type === "text") return textForCheckpoint(value.text);
		if (value.type === "toolCall" || value.type === "toolResult") return "";
		return "";
	}).filter(Boolean).join("\n");
	return blocks ? `[${role}]\n${blocks}` : "";
}

export default function piMemoryWorkbench(pi: ExtensionAPI): void {
	pi.on("session_start", async (event, ctx) => {
		lastInjectedProject = "";
		pendingCompactions.clear();
		suppressAutoContinueUntil = 0;
		restoreSessionState(ctx);
		memoryTodoWidget.resetCompletedDisplayState();
		let current = await refresh(ctx);
		if (!canWriteSessionMemory(current)) {
			if (ctx.hasUI && (event.reason === "resume" || event.reason === "fork" || event.reason === "new")) ctx.ui.notify(`Memory loaded read-only for non-owner session in ${current.paths.projectKey}. Report durable updates to the parent or owner session.`, "info");
			return;
		}
		const migration = await migrateLegacyMemoryLayout(ctx);
		current = await refresh(ctx);
		if (ctx.hasUI && migration.migrated) {
			ctx.ui.notify(migration.repairNeeded ? `Memory layout partially migrated for ${current.paths.projectKey}, but dashboard repair needs another /memory-migrate after concurrent changes. Session progress: ${current.paths.sessionProgressPath}.` : `Memory layout migrated for ${current.paths.projectKey}. Session progress: ${current.paths.sessionProgressPath}.`, migration.repairNeeded ? "warning" : "info");
		} else if (ctx.hasUI && (event.reason === "resume" || event.reason === "fork" || event.reason === "new")) {
			ctx.ui.notify(`Memory loaded for ${current.paths.projectKey}. Re-read ${current.paths.sessionProgressPath} and the session todo before continuing.`, "info");
		}
	});

	pi.on("session_shutdown", async (_event, ctx) => {
		if (ctx.hasUI) {
			memoryTodoWidget.dispose(ctx);
			ctx.ui.setStatus("pi-memory", undefined);
		}
	});

	pi.on("session_before_compact", async (event, ctx) => {
		const current = await refresh(ctx);
		if (!canWriteSessionMemory(current)) return;
		const boomerangCollapsed = isBoomerangJustCollapsed(event.branchEntries);
		const overflowRecovery = suppressAutoContinueUntil > Date.now();
		if (overflowRecovery) suppressAutoContinueUntil = 0;
		pendingCompactions.set(current.session.id, {
			sessionId: current.session.id,
			current,
			branchEntries: event.branchEntries,
			signal: event.signal,
			skipAutoContinue: boomerangCollapsed || overflowRecovery,
			skipCheckpointWrites: boomerangCollapsed,
		});
	});

	pi.on("session_compact", async (event, ctx) => {
		const currentAtCompact = await refresh(ctx);
		if (!canWriteSessionMemory(currentAtCompact)) return;
		const pending = pendingCompactions.get(currentAtCompact.session.id);
		pendingCompactions.delete(currentAtCompact.session.id);
		const overflowRecovery = suppressAutoContinueUntil > Date.now();
		if (overflowRecovery) suppressAutoContinueUntil = 0;
		let skipAutoContinue = Boolean(pending?.skipAutoContinue || overflowRecovery);
		let checkpointAborted = false;
		let writeResult: MemoryWriteResult | undefined;
		const current = pending?.current ?? currentAtCompact;

		if (pending?.skipCheckpointWrites) {
			memoryTodoWidget.resetCompletedDisplayState();
			await refresh(ctx);
			return;
		}

		const notableActivity = notableActivityForCheckpoint(pending?.branchEntries ?? [], event.compactionEntry.details);
		let checkpoint: MemoryCompactionCheckpoint | undefined;
		try {
			if (!ctx.model) throw new Error("pi-memory-workbench cannot generate compaction checkpoint: no model is selected");
			const auth = await ctx.modelRegistry.getApiKeyAndHeaders(ctx.model);
			if (!auth.ok) throw new Error(`pi-memory-workbench cannot generate compaction checkpoint: ${auth.error}`);
			if (!auth.apiKey) throw new Error(`pi-memory-workbench cannot generate compaction checkpoint: no API key resolved for ${ctx.model.provider}`);

			checkpoint = await generateMemoryCheckpoint({
				current,
				summary: event.compactionEntry.summary,
				branchEntries: pending?.branchEntries ?? [],
				firstKeptEntryId: event.compactionEntry.firstKeptEntryId,
				model: ctx.model,
				apiKey: auth.apiKey,
				headers: auth.headers,
				thinkingLevel: pi.getThinkingLevel(),
				notableActivity,
				signal: pending?.signal,
			});
		} catch (error) {
			const reason = error instanceof Error ? error.message : String(error);
			if (pending?.signal.aborted || isAbortLike(error)) {
				checkpointAborted = true;
				const message = `Compaction complete. Session memory checkpoint skipped due to abort: ${reason}. Re-read ${current.paths.sessionProgressPath} before continuing.`;
				if (ctx.hasUI) ctx.ui.notify(message, "warning");
				console.warn(message);
			} else {
				writeResult = await writeCompactionCheckpoint(current, event.compactionEntry.tokensBefore, reason, event.compactionEntry.summary, notableActivity);
				const message = `Compaction complete. Session memory checkpoint fallback used: ${reason}. Re-read ${current.paths.sessionProgressPath} before continuing.`;
				if (ctx.hasUI) ctx.ui.notify(message, "warning");
				console.warn(message);
			}
		}

		if (checkpoint) {
			try {
				writeResult = await applyMemoryCompactionCheckpoint(current, checkpoint);
				lastInjectedProject = "";
				if (ctx.hasUI) ctx.ui.notify(`Compaction complete. Session memory updated ${current.paths.sessionProgressPath}${writeResult.todoPath ? ` and ${writeResult.todoPath}` : ""}.`, "info");
			} catch (error) {
				const reason = error instanceof Error ? error.message : String(error);
				skipAutoContinue = true;
				const message = reason.startsWith("Memory conflict")
					? `Compaction complete. Session progress changed during checkpoint update: ${reason}. Re-read ${current.paths.sessionProgressPath} and recent memory events before continuing.`
					: `Compaction complete. Session memory checkpoint was generated, but applying it failed: ${reason}. Re-read ${current.paths.sessionProgressPath} and recent memory events before continuing.`;
				if (ctx.hasUI) ctx.ui.notify(message, "warning");
				console.warn(message);
			}
		}

		memoryTodoWidget.resetCompletedDisplayState();
		const refreshed = await refresh(ctx);
		await maybeAutoContinueAfterCompaction(pi, refreshed, event.compactionEntry.id, writeResult, checkpointAborted, skipAutoContinue);
		try {
			await createDreamIfStale(refreshed);
		} catch (error) {
			console.warn(`pi-memory-workbench dream skipped after compaction: ${error instanceof Error ? error.message : String(error)}`);
		}
	});

	pi.on("session_tree", async (_event, ctx) => {
		memoryTodoWidget.resetCompletedDisplayState();
		await refresh(ctx);
	});

	pi.on("agent_end", async (event, ctx) => {
		suppressAutoContinueUntil = isLikelyOverflowRecoveryEnding(event.messages, ctx.model?.contextWindow) ? Date.now() + OVERFLOW_RECOVERY_SUPPRESS_MS : 0;
		await refresh(ctx);
	});

	pi.on("before_agent_start", async (_event, ctx) => {
		memoryTodoWidget.hideCompletedTasksFromPreviousTurn();
		const current = await refresh(ctx);
		const injectionKey = `${current.paths.projectKey}:${current.session.id}`;
		const shouldInject = injectionKey !== lastInjectedProject || Boolean(current.parsedTodo) || current.dream.state !== "fresh";
		if (!shouldInject) return;
		lastInjectedProject = injectionKey;
		const reminder = canWriteSessionMemory(current)
			? "Reminder: memory is a guide, not a substitute for reading source files. Keep this session's progress.md and todo.md current when task state changes. Shared project progress.md is only a dashboard."
			: "Reminder: memory is a guide, not a substitute for reading source files. This non-owner session uses memory read-only; report durable progress, todos, dream candidates, or digest needs to the parent or owner session. Shared project progress.md is only a dashboard.";
		return {
			message: {
				customType: "pi-memory-workbench",
				content: `${memoryPacket(current)}\n\n${reminder}`,
				display: false,
			},
		};
	});

	pi.registerCommand("memory", {
		description: "Show current memory packet/status",
		handler: async (_args, ctx) => show(pi, ctx, memoryPacket(await refresh(ctx))),
	});

	pi.registerCommand("memory-refresh", {
		description: "Reload memory files and refresh memory chrome when enabled",
		handler: async (_args, ctx) => show(pi, ctx, `Memory refreshed for ${(await refresh(ctx)).paths.projectKey}.`),
	});

	pi.registerCommand("memory-migrate", {
		description: "Run bounded legacy memory migration and refresh the progress dashboard",
		handler: async (_args, ctx) => {
			assertMemoryWritesEnabled(await refresh(ctx), "migrate memory layout");
			const migration = await migrateLegacyMemoryLayout(ctx);
			const current = await refresh(ctx);
			if (!migration.repairNeeded) await refreshProgressDashboard(current);
			show(pi, ctx, migration.repairNeeded ? `Memory partially migrated, but dashboard repair needs another /memory-migrate after concurrent changes. Session progress: ${current.paths.sessionProgressPath}` : migration.migrated ? `Memory migrated. Session progress: ${current.paths.sessionProgressPath}` : `Memory already uses session/events layout. Dashboard refreshed: ${current.paths.progressPath}`);
		},
	});

	pi.registerCommand("memory-lint", {
		description: "Run read-only memory health checks",
		handler: async (_args, ctx) => show(pi, ctx, formatMemoryLintReport(await lintMemory(await refresh(ctx)))),
	});

	pi.registerCommand("memory-digest", {
		description: "Show or create non-destructive event digests: status|run",
		handler: async (args, ctx) => {
			const action = args.trim().toLowerCase() || "status";
			if (action === "status") return show(pi, ctx, formatMemoryDigestStatus(await getMemoryDigestStatus(await refresh(ctx))));
			if (action !== "run") return show(pi, ctx, "Usage: /memory-digest status|run");
			const result = await createMemoryDigest(await refreshForExplicitWrite(ctx));
			show(pi, ctx, `Created memory event digest: ${result.path}\nComplete through: ${result.completeThrough}\nSource events: ${result.sourceEventCount}`);
		},
	});

	pi.registerCommand("memory-autocontinue", {
		description: "Configure hidden follow-up turns after non-aborted compactions: status|on|off (auto/always aliases for on)",
		handler: async (args, ctx) => {
			const value = args.trim().toLowerCase();
			if (!value || value === "status") return show(pi, ctx, autoContinueStatus());
			const mode = autoContinueModeFromCommand(value);
			if (!mode) return show(pi, ctx, "Usage: /memory-autocontinue status|on|off (auto/always are legacy aliases for on)");
			autoContinueMode = mode;
			pi.appendEntry(AUTO_CONTINUE_SETTINGS_TYPE, { mode, timestamp: new Date().toISOString() });
			show(pi, ctx, autoContinueStatus());
