async function updateTodoCommand(pi: ExtensionAPI, ctx: ExtensionContext, args: string, status: "doing" | "done" | "blocked"): Promise<void> {
	const match = args.trim().match(/^(\d+)\s+(.+)$/s);
	if (!match) return show(pi, ctx, `Usage: /todo-${status} <index> <exact current item text>`);
	const index = Number(match[1]);
	if (index < 1) return show(pi, ctx, `Usage: /todo-${status} <index> <exact current item text>`);
	const expectedText = match[2]?.trim();
	if (!expectedText) return show(pi, ctx, `Usage: /todo-${status} <index> <exact current item text>`);
	const path = await updateTodoStatus(await refreshForWrite(ctx), index, status, expectedText);
	show(pi, ctx, `Updated todo #${index} in ${path}`);
	await refresh(ctx);
}

function lineValue(content: string, label: string): string | undefined {
	const escaped = label.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
	const match = content.match(new RegExp(`^-\\s*${escaped}:\\s*(.*)$`, "im"));
	return match?.[1]?.trim() || undefined;
}

function isBoomerangJustCollapsed(branchEntries: CheckpointEntry[]): boolean {
	let tailIndex = branchEntries.length - 1;
	while (tailIndex >= 0) {
		const entry = branchEntries[tailIndex];
		if (entry?.type !== "custom_message" || entry.customType !== "boomerang-handoff") break;
		tailIndex -= 1;
	}

	const details = branchEntries[tailIndex]?.details;
	if (!details || typeof details !== "object" || Array.isArray(details)) return false;
	const value = details as Record<string, unknown>;
	return typeof value.task === "string"
		&& typeof value.commandCount === "number"
		&& Array.isArray(value.readFiles)
		&& Array.isArray(value.modifiedFiles)
		&& Array.isArray(value.validationCommands)
		&& Array.isArray(value.failedOperations);
}

function notableActivityForCheckpoint(branchEntries: CheckpointEntry[], details: unknown): string {
	const toolCalls: string[] = [];
	const readFiles = new Set<string>();
	const fileEdits = new Set<string>();
	const pendingCalls = new Map<string, { name: string; args: Record<string, unknown> }>();
	const compactionDetails = details && typeof details === "object" && !Array.isArray(details) ? details as { readFiles?: unknown; modifiedFiles?: unknown } : undefined;

	if (branchEntries.length === 0) {
		if (Array.isArray(compactionDetails?.readFiles)) for (const file of compactionDetails.readFiles) if (typeof file === "string") readFiles.add(file);
		if (Array.isArray(compactionDetails?.modifiedFiles)) for (const file of compactionDetails.modifiedFiles) if (typeof file === "string") fileEdits.add(file);
	}

	for (const entry of branchEntries) {
		if (entry.type !== "message" || !entry.message || typeof entry.message !== "object") continue;
		const message = entry.message as Record<string, unknown>;
		if (!Array.isArray(message.content)) continue;
		if (message.role === "assistant") {
			for (const block of message.content) {
				if (!block || typeof block !== "object") continue;
				const value = block as Record<string, unknown>;
				if (value.type !== "toolCall" || typeof value.id !== "string" || typeof value.name !== "string") continue;
				const args = value.arguments && typeof value.arguments === "object" && !Array.isArray(value.arguments) ? value.arguments as Record<string, unknown> : {};
				pendingCalls.set(value.id, { name: value.name, args });
			}
		}
		if (message.role !== "toolResult") continue;
		const toolCallId = typeof message.toolCallId === "string" ? message.toolCallId : undefined;
		const call = toolCallId ? pendingCalls.get(toolCallId) : undefined;
		if (toolCallId) pendingCalls.delete(toolCallId);
		const resultText = message.content.map((block) => block && typeof block === "object" && "text" in block ? String((block as { text?: unknown }).text ?? "") : "").join("\n").trim();
		if (!call || message.isError === true || !resultText || /^\(?no output\)?$/i.test(resultText)) continue;
		toolCalls.push(formatToolCall(call.name, call.args));
		if (call.name === "read" && typeof call.args.path === "string") readFiles.add(call.args.path);
		if ((call.name === "edit" || call.name === "write") && typeof call.args.path === "string") fileEdits.add(call.args.path);
	}

	const sections = [
		formatList("Useful tool calls", [...new Set(toolCalls)].slice(-20)),
		formatList("Read files", [...readFiles].slice(-30)),
		formatList("File edits", [...fileEdits].slice(-30)),
	].filter(Boolean);
	return sections.join("\n") || "No notable activity captured.";
}

function formatToolCall(name: string, args: Record<string, unknown>): string {
	if (name === "read" && typeof args.path === "string") return `read ${args.path}`;
	if (name === "edit" && typeof args.path === "string") return `edit ${args.path}`;
	if (name === "write" && typeof args.path === "string") return `write ${args.path}`;
	if (name === "bash") return `bash ${typeof args.command === "string" ? redactBashCommand(args.command) : "[command omitted]"}`;
	return `${name} [arguments omitted]`;
}

function redactBashCommand(command: string): string {
	const value = String.raw`(?:"[^"]*"|'[^']*'|\`[^\`]*\`|[^\s]+)`;
	return redactSensitiveText(command)
		.replace(new RegExp(String.raw`\b((?:export\s+)?(?:(?:[A-Z_][A-Z0-9_]*_)?(?:TOKEN|SECRET|PASSWORD|PASSWD|PWD|API_KEY|PRIVATE_KEY)|[A-Z_][A-Z0-9_]*(?:TOKEN|SECRET|PASSWORD|PASSWD|API_KEY|PRIVATE_KEY))\s*=\s*)${value}`, "gi"), "$1[REDACTED]")
		.replace(new RegExp(String.raw`(^|\s)(--?(?:api[-_]?key|token|access[-_]?token|auth[-_]?token|bearer[-_]?token|refresh[-_]?token|secret|password|passwd|pwd)(?:\s*=\s*|\s+))${value}`, "gi"), "$1$2[REDACTED]")
		.slice(0, 160);
}

function isAbortLike(error: unknown): boolean {
	if (!error || typeof error !== "object") return false;
	const value = error as { name?: unknown; message?: unknown; code?: unknown };
	return value.name === "AbortError"
		|| value.code === "ABORT_ERR"
		|| (typeof value.message === "string" && /\b(aborted|abort|cancelled|canceled)\b/i.test(value.message));
}

function formatList(title: string, items: string[]): string {
	return items.length ? `${title}:\n${items.map((item) => `- ${item}`).join("\n")}` : "";
}

