export function memoryWritesDisabledMessage(state: MemoryState, action = "write session memory"): string {
	if (state.session.memoryMode === "owner") return `Cannot ${action}.`;
	return `Cannot ${action}: this is not a confirmed owner session, so pi-memory-workbench is read-only. Report durable progress, todos, dream candidates, or digest needs to the parent or owner session instead.`;
}

export const MEMORY_COMPACTION_INSTRUCTIONS = `Create exactly one memory checkpoint block for pi-memory-workbench.

Use the memory packet, native Pi compaction summary, notable activity, and retained recent context for the latest state. Treat earlier packets, progress/todo notes, and compaction summaries as stale unless later context confirms them. Do not copy old TODO/DOING/BLOCKED lines; if work was implemented, reviewed, validated, or unblocked, report that outcome.

Return only this XML block, with real values in every tag:

<pi-memory-checkpoint>
<objective></objective>
<current-state></current-state>
<next-action></next-action>
<active-files>
-
</active-files>
<blockers></blockers>
<last-verified-command></last-verified-command>
<progress-update></progress-update>
<todo-title></todo-title>
<todo-update>
</todo-update>
</pi-memory-checkpoint>

Do not put XML tags inside field values. Use "None." for blockers when there are none and "Not recorded." for last verified command when unknown. Leave todo-title empty unless a new todo must be created. In todo-update, write plain markdown prose; include concise lists of notable useful tool calls, notable read files, and file edits when available, plus any manual follow-up. Do not use level-2 headings or TODO/DOING/DONE/BLOCKED-prefixed bullets.`;

export async function loadMemoryState(ctx: ExtensionContext): Promise<MemoryState> {
	const session = sessionIdentity(ctx);
	const paths = await resolveMemoryPaths(ctx.cwd, session);
	const dashboard = await readOptional(paths.progressPath);
	const progress = await readOptional(paths.sessionProgressPath);
	const projectMemory = await readOptional(paths.memoryPath);
	const currentTodo = await readOptional(paths.currentTodoPath);
	const activeTodoPath = await exists(paths.sessionTodoPath) ? paths.sessionTodoPath : undefined;
	const activeTodo = activeTodoPath ? await readOptional(activeTodoPath) : undefined;
	return {
		paths,
		session,
		dashboard,
		progress,
		projectMemory,
		currentTodo,
		activeTodoPath,
		activeTodo,
		parsedTodo: activeTodo ? parseTodo(activeTodo) : undefined,
		recentEvents: await recentMemoryEvents(paths),
		recentSessions: await recentSessionSummaries(paths),
		hashes: {
			dashboard: await fileSnapshot(paths.progressPath),
			sessionProgress: await fileSnapshot(paths.sessionProgressPath),
			sessionTodo: await fileSnapshot(paths.sessionTodoPath),
			memory: await fileSnapshot(paths.memoryPath),
		},
		dream: await getDreamStatus(paths),
	};
}

export async function migrateLegacyMemoryLayout(ctx: ExtensionContext): Promise<{ migrated: boolean; eventPath?: string; repairNeeded?: boolean }> {
	let state = await loadMemoryState(ctx);
	if (state.dashboard?.trimStart().startsWith(MEMORY_LAYOUT_MARKER)) return { migrated: false };

	if (!state.dashboard?.trim()) {
		await refreshProgressDashboard(state);
		return { migrated: true };
	}

	const legacyDashboardSnapshot = state.hashes.dashboard;
	const legacyTodo = await readLegacyActiveTodo(state);
	const eventPath = await writeMemoryEvent(state, "migration", `## Summary
Legacy progress.md was archived and used to seed session progress.

## Legacy progress.md

\`\`\`md
${state.dashboard.replace(/```/g, "` ` `")}
\`\`\`

## Legacy todo
${legacyTodo?.error ? `Legacy todo could not be imported: ${legacyTodo.error}` : legacyTodo?.path ? `Detected legacy active todo: ${legacyTodo.path}${legacyTodo.content ? "" : " (missing target)"}.` : "No legacy active todo detected."}`);

	if (!state.progress) {
		const resume = extractSection(state.dashboard, "Resume Here") || extractSection(state.dashboard, "Current Focus");
		const seeded = defaultSessionProgress(state, {
			objective: "Seeded from legacy progress.md.",
			currentState: resume ? clip(resume.replace(/\s+/g, " "), 600) : `Legacy progress content was archived in ${eventPath}.`,
			nextAction: "Read the archived migration event and continue this session's task.",
			activeFiles: [],
			blockers: "None.",
			lastVerifiedCommand: "Not recorded.",
		});
		await mutateFileIfUnchanged(state.paths.sessionProgressPath, state.hashes.sessionProgress, () => appendUpdate(seeded, `Seeded this session from legacy progress.md; archived raw content in ${eventPath}.`));
	}

	if (!state.activeTodo && legacyTodo?.content) {
		await mutateFileIfUnchanged(state.paths.sessionTodoPath, state.hashes.sessionTodo, () => appendNote(withSessionTodoMetadata(state, legacyTodo.content ?? ""), `Imported from legacy active todo ${legacyTodo.path}.`));
	}

	state = await loadMemoryState(ctx);
	try {
		await mutateFileIfUnchanged(state.paths.progressPath, legacyDashboardSnapshot, () => renderDashboard(state));
	} catch {
		const latestDashboard = await readOptional(state.paths.progressPath);
		if (latestDashboard?.trimStart().startsWith(MEMORY_LAYOUT_MARKER)) return { migrated: true, eventPath };
		if (latestDashboard?.trim()) {
			const latestSnapshot = await fileSnapshot(state.paths.progressPath);
			await writeMemoryEvent(state, "migration", `## Summary
Concurrent legacy progress.md content was archived during migration retry.

## Legacy progress.md

\`\`\`md
${latestDashboard.replace(/```/g, "` ` `")}
\`\`\``);
			try {
				await mutateFileIfUnchanged(state.paths.progressPath, latestSnapshot, () => renderDashboard(state));
			} catch {
				return { migrated: true, eventPath, repairNeeded: true };
			}
		} else {
			return { migrated: true, eventPath, repairNeeded: true };
		}
	}
	return { migrated: true, eventPath };
}

export async function refreshProgressDashboard(state: MemoryState): Promise<void> {
	try {
		await mutateFile(state.paths.progressPath, () => renderDashboard(state));
	} catch (error) {
		console.warn(`pi-memory-workbench dashboard refresh skipped: ${error instanceof Error ? error.message : String(error)}`);
	}
}

async function getDreamStatus(paths: MemoryPaths): Promise<DreamStatus> {
	const lastRun = await readOptional(paths.lastRunPath);
	let date: Date | undefined;
	if (lastRun) {
		const match = lastRun.match(/Last run:\s*(.+)/i);
		date = new Date((match?.[1] ?? lastRun.trim()).trim());
		if (Number.isNaN(date.getTime())) date = undefined;
	}
	const latest = (await recentMarkdownFiles(paths.dreamsDir, 1, { exclude: ["last-run.md"] }))[0];
	if (!date && latest) date = new Date(latest.mtimeMs);
	if (!date) return { state: "never", latestDreamPath: latest?.path };
	const ageHours = Math.round((Date.now() - date.getTime()) / 3_600_000);
	return { state: ageHours <= 24 ? "fresh" : "stale", lastRun: date, ageHours, latestDreamPath: latest?.path };
}

export function memoryPacket(state: MemoryState): string {
	const lines = [
		`Memory packet for project \`${state.paths.projectKey}\`:`,
		`- dashboard progress.md: ${state.paths.progressPath}${state.dashboard ? "" : " (missing)"} (non-authoritative)`,
		`- session progress.md: ${state.paths.sessionProgressPath}${state.progress ? "" : " (missing)"}`,
		`- memory.md: ${state.paths.memoryPath}${state.projectMemory ? "" : " (missing)"}`,
		`- session todo.md: ${state.paths.sessionTodoPath}${state.activeTodo ? "" : " (missing)"}`,
		`- legacy todos/current.md: ${state.paths.currentTodoPath}${state.currentTodo ? "" : " (missing)"} (migration source only; do not update)`,
		`- events: ${state.paths.eventsDir}${state.recentEvents.length ? ` (${state.recentEvents.length} recent)` : ""}`,
		`- dreams: ${formatDreamStatus(state.dream)}`,
	];
	lines.push(`- session: ${state.session.id}${state.session.parentSession ? ` (parent: ${state.session.parentSession})` : ""}`);
	lines.push(`- memory mode: ${state.session.memoryMode}${state.session.memoryMode === "readonly" ? " (read-only; owner session owns durable memory writes)" : ""}`);

	const resume = extractSection(state.progress, "Resume Here") || extractSection(state.progress, "Current Focus");
	if (resume) lines.push("", "Session progress summary:", clip(resume, 900));
	if (state.projectMemory) lines.push("", projectMemoryHotView(state.projectMemory));
	if (state.parsedTodo) {
		lines.push("", `Session todo: ${state.parsedTodo.title}`);
		const doing = state.parsedTodo.items.find((item) => item.status === "doing");
		if (doing) lines.push(`DOING: ${doing.text}`);
		const next = state.parsedTodo.items.filter((item) => item.status === "todo" || item.status === "blocked").slice(0, 5);
		for (const item of next) lines.push(`${item.status.toUpperCase()} #${item.index}: ${item.text}`);
	}
	if (state.recentEvents.length) {
		lines.push("", "Recent memory events:");
		for (const event of state.recentEvents.slice(0, 5)) lines.push(`- ${event.kind}: ${relativeFrom(state.paths.projectDir, event.path)}${event.summary ? ` — ${clip(event.summary, 120)}` : ""}`);
	}
	return lines.join("\n");
}

export function projectMemoryHotView(content: string, perSection = 2): string {
	const parsed = parseProjectMemorySchema(content);
	const active = parsed.entries.filter((entry) => entry.section !== "Deferred" && entry.status === "active");
	const selected = [] as typeof active;
	const limit = Math.max(1, Math.min(5, Math.floor(perSection)));
	for (const section of ["Decisions", "Conventions", "Gotchas", "Avoid", "Verified Commands"]) {
		selected.push(...active.filter((entry) => entry.section === section).slice(-limit));
	}
	const superseded = parsed.entries.filter((entry) => entry.status === "superseded").length;
	const deferred = parsed.entries.filter((entry) => entry.section === "Deferred").length;
	const lines = [`Project memory hot view (${active.length} active, ${superseded} superseded, ${deferred} deferred):`];
	for (const entry of selected) lines.push(`- [${entry.section}: ${entry.id ?? "unidentified"}] ${clip(entry.text, 180)}`);
	if (!selected.length) lines.push("- No active schema memory entries.");
	const omitted = active.length - selected.length;
	if (omitted > 0) lines.push(`- ${omitted} active entr${omitted === 1 ? "y" : "ies"} omitted; use memory_recall to search and expand exact sources.`);
	else lines.push("- Use memory_recall to search source events, Dreams, digests, or session history when needed.");
	return lines.join("\n");
}

export function formatDreamStatus(dream: DreamStatus): string {
	if (dream.state === "never") return "never run";
	return `${dream.state}${dream.ageHours === undefined ? "" : ` (${dream.ageHours}h)`}`;
}

function extractSection(content: string | undefined, heading: string): string | undefined {
	if (!content) return undefined;
	const pattern = new RegExp(`^##\\s+${escapeRegex(heading)}\\s*$`, "im");
	const match = pattern.exec(content);
	if (!match) return undefined;
	const start = match.index + match[0].length;
	const rest = content.slice(start);
	const next = rest.search(/^##\s+/m);
	return (next >= 0 ? rest.slice(0, next) : rest).trim() || undefined;
}

function firstSummarySection(content: string, headings: string[]): string | undefined {
	for (const heading of headings) {
		const section = extractSection(content, heading);
		if (section) return section;
	}
	return undefined;
}

function compactSummarySection(content: string | undefined): string | undefined {
	if (!content?.trim()) return undefined;
	const value = content.split(/\r?\n/)
		.map((line) => line.replace(/^\s*[-*+]\s+/, "").replace(/^\s{0,3}#{1,6}\s+/, "").trim())
		.filter((line) => line && !/^```/.test(line))
		.join(" ");
	return value ? sanitizeProgressScalar(value.slice(0, 1200), "") || undefined : undefined;
}

function resumeLineValue(resume: string, label: string): string | undefined {
	const match = resume.match(new RegExp(`^-\\s*${escapeRegex(label)}:\\s*(.+)$`, "im"));
	return match?.[1]?.trim() || undefined;
}

function uniquePaths(contents: string[]): string[] {
	const paths = new Set<string>();
	for (const content of contents) {
		for (const match of content.matchAll(/(?:\.{0,2}\/|\/)?(?:[\w.@-]+\/)*[\w.@-]+\.(?:ts|tsx|js|jsx|json|md|ya?ml)\b/g)) {
			if (match[0]) paths.add(match[0]);
			if (paths.size >= 30) return [...paths];
		}
	}
	return [...paths];
}

export async function createActiveTodo(state: MemoryState, title: string): Promise<string> {
	if (state.activeTodoPath || await exists(state.paths.sessionTodoPath)) throw new Error(`Session todo already exists at ${state.paths.sessionTodoPath}. Refusing to overwrite it.`);
	const safeTitle = sanitizeTodoLine(title, "Todo title");
	const content = createSessionTodoMarkdown(state, safeTitle);
	await mutateFileIfUnchanged(state.paths.sessionTodoPath, state.hashes.sessionTodo, () => content);
	await writeMemoryEvent(state, "todo", `## Summary
Created session todo: ${safeTitle || "Untitled task"}.

## Todo path
${state.paths.sessionTodoPath}`);
	await refreshProgressDashboard({ ...state, activeTodoPath: state.paths.sessionTodoPath, activeTodo: content });
	return state.paths.sessionTodoPath;
}

export async function addTodoItem(state: MemoryState, text: string): Promise<string> {
	const safeText = sanitizeTodoLine(text, "Todo item");
	const todoPath = await ensureActiveTodo(state, "Current task");
	await mutateFile(todoPath, (current) => appendTodoItem(current, safeText));
	await writeMemoryEvent(state, "todo", `## Summary
Added session todo item: ${sanitizeProgressScalar(safeText, "Not recorded.")}.`);
	return todoPath;
}

export async function updateTodoStatus(state: MemoryState, index: number, status: TodoStatus, expectedText?: string): Promise<string> {
	if (!state.activeTodoPath || !state.activeTodo) throw new Error("No session todo exists. Create one with /todo-new before updating item status.");
	const todoPath = state.activeTodoPath;
	const loadedText = state.parsedTodo?.items.find((item) => item.index === index)?.text;
	const requiredText = expectedText === undefined ? loadedText : sanitizeTodoLine(expectedText, "Expected todo text");
	if (!requiredText) throw new Error(`Todo item #${index} not found`);
	if (loadedText !== requiredText) throw new Error(`Todo item #${index} is ${loadedText ? `"${loadedText}"` : "missing"}, expected "${requiredText}". Re-read memory and retry.`);
	await mutateFileIfUnchanged(todoPath, state.hashes.sessionTodo, (current) => {
		const parsed = parseTodo(current);
		const currentText = parsed.items.find((item) => item.index === index)?.text;
		if (currentText !== requiredText) throw new Error(`Todo item #${index} changed since it was read. Re-read memory and retry.`);
		return setTodoStatus(current, index, status);
	});
	await writeMemoryEvent(state, "todo", `## Summary
Marked session todo #${index} as ${status}.`);
	return todoPath;
}

export async function writeCheckpoint(state: MemoryState, params: {
	objective: string;
	currentState: string;
	nextAction: string;
	activeFiles?: string[];
	blockers?: string;
	lastVerifiedCommand?: string;
	update?: string;
}): Promise<MemoryWriteResult> {
	await updateSessionProgress(state, params, state.hashes.sessionProgress);
	const eventPath = await writeMemoryEvent(state, "checkpoint", checkpointEventBody(params));
	await refreshProgressDashboard({ ...state, progress: await readOptional(state.paths.sessionProgressPath) });
	return { progressUpdated: true, todoPath: state.activeTodoPath, eventPath };
}

export function buildDeterministicCompactionCheckpoint(state: MemoryState, params: {
	summary: string;
	notableActivity?: string;
	reason?: string;
}): MemoryCompactionCheckpoint {
	const resume = extractSection(state.progress, "Resume Here") ?? "";
	const existing = (label: string) => resumeLineValue(resume, label);
	const objective = compactSummarySection(firstSummarySection(params.summary, ["Goal", "Objective", "Current Objective"]))
		?? existing("Current objective")
		?? "Continue the current session task.";
	const structuredState = compactSummarySection(firstSummarySection(params.summary, ["Current State", "Progress", "Completed", "Summary"]));
	const currentState = structuredState
		?? compactSummarySection(params.summary)
		?? existing("Current state")
		?? "Native compaction completed; detailed state was not recoverable.";
	const nextAction = compactSummarySection(firstSummarySection(params.summary, ["Next Action", "Next Steps", "Remaining Work", "Remaining Tasks"]))
		?? existing("Next action")
		?? "Re-read session progress, todo, and recent events before continuing.";
	const blockers = compactSummarySection(firstSummarySection(params.summary, ["Blockers", "Open Questions", "Risks"]))
		?? existing("Blockers/open questions")
		?? "None recorded.";
	const lastVerifiedCommand = compactSummarySection(firstSummarySection(params.summary, ["Last Verified Command", "Verification", "Tests", "Validation"]))
		?? existing("Last verified command")
		?? "Not recorded.";
	const activeFiles = uniquePaths([
		firstSummarySection(params.summary, ["Active Files", "Files", "Files Changed", "Modified Files"]) ?? "",
		params.notableActivity ?? "",
	]);
	const reason = sanitizeProgressScalar(params.reason, "Focused checkpoint generation was unavailable.");
	return {
		objective,
		currentState,
		nextAction,
		activeFiles,
		blockers,
		lastVerifiedCommand,
		progressUpdate: `Compaction checkpoint restored with deterministic fallback: ${reason}`,
		todoUpdate: `Deterministic fallback checkpoint used because ${reason}\n\nNative summary:\n${clip(params.summary || "Not recorded.", 1200)}\n\nNotable activity:\n${clip(params.notableActivity || "No notable activity captured.", 1200)}`,
	};
}

export async function writeCompactionCheckpoint(state: MemoryState, tokensBefore: number, reason = "Memory checkpoint fallback used.", summary = "Not recorded.", notableActivity = "No notable activity captured."): Promise<MemoryWriteResult> {
	const checkpoint = buildDeterministicCompactionCheckpoint(state, { summary, notableActivity, reason });
	await updateSessionProgress(state, {
		objective: checkpoint.objective,
		currentState: checkpoint.currentState,
		nextAction: checkpoint.nextAction,
		activeFiles: checkpoint.activeFiles,
		blockers: checkpoint.blockers,
		lastVerifiedCommand: checkpoint.lastVerifiedCommand,
		update: checkpoint.progressUpdate,
	}, state.hashes.sessionProgress);
	const eventPath = await writeMemoryEvent(state, "compaction-fallback", `## Summary
${checkpoint.progressUpdate}

## Objective
${checkpoint.objective}

## Current State
${checkpoint.currentState}

## Next Action
${checkpoint.nextAction}

## Native compaction
Tokens before compaction: ${tokensBefore}.

${summary}

## Notable Activity
${notableActivity}`);
	if (state.activeTodoPath && await exists(state.activeTodoPath)) {
		await mutateFileIfUnchanged(state.activeTodoPath, state.hashes.sessionTodo, (current) => appendTodoCheckpoint(current, checkpoint.todoUpdate));
	}
	await refreshProgressDashboard({ ...state, progress: await readOptional(state.paths.sessionProgressPath) });
	return { progressUpdated: true, todoPath: state.activeTodoPath, eventPath };
}

export function parseMemoryCompactionCheckpoint(content: string): MemoryCompactionCheckpoint {
	const block = taggedValue(content, "pi-memory-checkpoint");
	if (!block) throw new Error("Missing <pi-memory-checkpoint> block in compaction summary");

	const missing: string[] = [];
	const required = (tag: string): string => {
		const value = taggedValue(block, tag)?.trim();
		if (!value) missing.push(tag);
		return value ?? "";
	};

	const objectiveValue = required("objective");
	const currentStateValue = required("current-state");
	const nextActionValue = required("next-action");
	const activeFilesValue = required("active-files");
	const blockersValue = required("blockers");
	const lastVerifiedCommandValue = required("last-verified-command");
	const progressUpdateValue = required("progress-update");
	const todoTitleValue = taggedValue(block, "todo-title")?.trim() || undefined;
	const todoUpdate = required("todo-update");

	const placeholders = [
		["objective", objectiveValue],
		["current-state", currentStateValue],
		["next-action", nextActionValue],
		["active-files", activeFilesValue],
		["blockers", blockersValue],
		["last-verified-command", lastVerifiedCommandValue],
		["progress-update", progressUpdateValue],
		["todo-title", todoTitleValue],
		["todo-update", todoUpdate],
	].filter(([, value]) => isCopiedTemplatePlaceholder(value)).map(([tag]) => tag);

	if (isEmptyActiveFilesTemplate(activeFilesValue)) placeholders.push("active-files");

	if (missing.length || placeholders.length) {
		const details = [
			missing.length ? `missing: ${missing.join(", ")}` : undefined,
			placeholders.length ? `copied placeholders: ${placeholders.join(", ")}` : undefined,
		].filter(Boolean).join("; ");
		throw new Error(`Invalid <pi-memory-checkpoint> block; ${details}`);
	}

	const invalidScalars = [
		["objective", objectiveValue],
		["current-state", currentStateValue],
		["next-action", nextActionValue],
		["blockers", blockersValue],
		["last-verified-command", lastVerifiedCommandValue],
		["progress-update", progressUpdateValue],
		["todo-title", todoTitleValue],
	].filter(([, value]) => value && hasUnsafeCheckpointScalar(value));
	if (invalidScalars.length) throw new Error(`Invalid <pi-memory-checkpoint> block; unsafe scalar fields: ${invalidScalars.map(([tag]) => tag).join(", ")}`);

	return {
		objective: sanitizeProgressScalar(objectiveValue, "Not recorded."),
		currentState: sanitizeProgressScalar(currentStateValue, "Not recorded."),
		nextAction: sanitizeProgressScalar(nextActionValue, "Not recorded."),
		activeFiles: parseActiveFiles(activeFilesValue).map((file) => sanitizeProgressScalar(file, "Unnamed file.")),
		blockers: sanitizeProgressScalar(blockersValue, "None."),
		lastVerifiedCommand: sanitizeProgressScalar(lastVerifiedCommandValue, "Not recorded."),
		progressUpdate: sanitizeProgressScalar(progressUpdateValue, "Not recorded."),
		todoTitle: todoTitleValue ? sanitizeProgressScalar(todoTitleValue, "") || undefined : undefined,
		todoUpdate,
	};
}

export async function applyMemoryCompactionCheckpoint(state: MemoryState, checkpoint: MemoryCompactionCheckpoint): Promise<MemoryWriteResult> {
	const todoPath = checkpoint.todoTitle ? await ensureActiveTodo(state, checkpoint.todoTitle) : state.activeTodoPath;
	await updateSessionProgress({ ...state, activeTodoPath: todoPath }, {
		objective: checkpoint.objective,
		currentState: checkpoint.currentState,
		nextAction: checkpoint.nextAction,
		activeFiles: checkpoint.activeFiles,
		blockers: checkpoint.blockers,
		lastVerifiedCommand: checkpoint.lastVerifiedCommand,
		update: checkpoint.progressUpdate,
	}, state.hashes.sessionProgress);
	const eventPath = await writeMemoryEvent(state, "compaction", `## Summary
${checkpoint.progressUpdate}

## Objective
${checkpoint.objective}

## Current State
${checkpoint.currentState}

## Next Action
${checkpoint.nextAction}

## Intended Todo Update
${checkpoint.todoUpdate}`);
	if (todoPath && await exists(todoPath)) await mutateFileIfUnchanged(todoPath, todoPath === state.activeTodoPath ? state.hashes.sessionTodo : await fileSnapshot(todoPath), (current) => appendTodoCheckpoint(current, checkpoint.todoUpdate));
	await refreshProgressDashboard({ ...state, progress: await readOptional(state.paths.sessionProgressPath), activeTodoPath: todoPath, activeTodo: todoPath ? await readOptional(todoPath) : undefined });
	return { progressUpdated: true, todoPath, eventPath };
}

export async function createDream(state: MemoryState): Promise<string> {
	const recentTodos = await recentTodoSummaries(state);
	const now = new Date().toISOString();
	const eventSnapshots = await recentEventSnapshots(state);
	const digestSnapshots = await recentDigestSnapshots(state);
	const sources = dreamSources(state, eventSnapshots, digestSnapshots, recentTodos);
	const candidates = extractMemoryCandidates(sources);
	const result = await applyDreamMemoryCandidates({ paths: state.paths, expected: state.hashes.memory, candidates, now });
	const memoryRefs = uniqueRefs([
		...[...result.applied, ...result.deferred].map((entry) => `${entry.ref} (${entry.id})`),
		...result.superseded.map((entry) => `memory.md#${entry.section.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "")} (${entry.id})`),
	]);
	const digestRefs = digestSnapshots.map((digest) => digest.path);
	const metadata = formatMemoryEventMetadataV1({
		kind: "dream",
		created: now,
		sessionId: state.session.id,
		actorKind: state.session.actorKind,
		parentSession: state.session.parentSession,
		project: state.paths.projectKey,
		sessionProgress: relativeFrom(state.paths.projectDir, state.paths.sessionProgressPath),
		sessionTodo: relativeFrom(state.paths.projectDir, state.paths.sessionTodoPath),
		memory: relativeFrom(state.paths.projectDir, state.paths.memoryPath),
		sourceHashes: dreamSourceHashes(state, eventSnapshots, digestSnapshots, recentTodos),
		memoryRefs,
		digestRefs,
	});
	const content = `# Dream: ${now}\n\n${metadata}\n\nStatus: applied\nApplied: yes\nMemory hash before: ${result.memoryHashBefore ?? "missing"}\nMemory hash after: ${result.memoryHashAfter ?? "missing"}\n\n## Sources reviewed\n${formatSourceList(sources.filter((source) => source.kind !== "event" && source.kind !== "event-digest"))}\n\n## Digest sources reviewed\n${formatSourceList(sources.filter((source) => source.kind === "event-digest"))}\n\n## Raw event sources reviewed\n${formatSourceList(sources.filter((source) => source.kind === "event"))}\n\n## Recent progress snapshot\n${clip(extractSection(state.progress, "Updates") || state.progress || "No session progress content found.", 2000)}\n\n## Recent event snapshot\n${eventSnapshots.map((event) => `### ${basename(event.path)}\n${clip(event.content, 900)}`).join("\n\n") || "No event files found."}\n\n## Recent digest snapshot\n${digestSnapshots.map((digest) => `### ${basename(digest.path)}\n${clip(digest.content, 900)}`).join("\n\n") || "No digest files found."}\n\n## Recent todo snapshot\n${[state.activeTodo ? { path: relativeFrom(state.paths.projectDir, state.paths.sessionTodoPath), content: state.activeTodo } : undefined, ...recentTodos].filter((todo): todo is { path: string; content: string } => Boolean(todo)).map((todo) => `### ${basename(todo.path)}\n${clip(todo.content, 1200)}`).join("\n\n") || "No todo files found."}\n\n## Applied to memory.md\n${formatDreamEntries(result.applied, "No new durable memory candidates were applied.")}\n\n## Superseded\n${result.superseded.length ? result.superseded.map((entry) => `- [${entry.id}] ${entry.text} (superseded-by: ${entry.supersededBy}; source: ${entry.sources.join(", ")})`).join("\n") : "No durable memory entries were superseded."}\n\n## Skipped duplicates\n${result.skippedDuplicates.length ? result.skippedDuplicates.map((entry) => `- ${entry.existingId ? `[existing: ${entry.existingId}] ` : ""}${entry.text} (source: ${entry.sources.join(", ")})`).join("\n") : "No duplicate candidates were skipped."}\n\n## Deferred\n${formatDreamEntries(result.deferred, "No candidates were deferred.")}\n\n## Auto-apply policy\n${dreamAutoApplyPolicy().map((line) => `- ${line}`).join("\n")}\n\n## Migration note\n${result.legacyPreserved ? "Existing freeform memory.md was preserved under `## Legacy Memory` during schema-v1 migration." : "No legacy freeform memory migration was needed."}\n`;
	const dreamPath = await writeMemoryEventFile({ ...state.paths, eventsDir: state.paths.dreamsDir }, state.session.safeId, "dream", content);
	await mutateFile(state.paths.lastRunPath, () => `Last run: ${now}\nLatest dream: ./${basename(dreamPath)}\nApplied to memory.md: ${result.applied.length}\nSuperseded: ${result.superseded.length}\nSkipped duplicates: ${result.skippedDuplicates.length}\nDeferred: ${result.deferred.length}\n`);
	return dreamPath;
}

export async function createDreamIfStale(state: MemoryState): Promise<string | undefined> {
	if (state.dream.state === "fresh") return undefined;
	return createDream(state);
}

async function updateSessionProgress(state: MemoryState, params: {
	objective: string;
	currentState: string;
	nextAction: string;
	activeFiles?: string[];
	blockers?: string;
	lastVerifiedCommand?: string;
	update?: string;
}, expected: FileSnapshot | undefined): Promise<void> {
	await mutateFileIfUnchanged(state.paths.sessionProgressPath, expected, (current) => {
		const base = current || defaultSessionProgress(state);
		const withMetadata = updateSessionMetadata(base, state);
		const next = replaceSection(withMetadata, "Resume Here", resumeSection(state, params));
		return params.update?.trim() ? appendUpdate(next, params.update) : next;
	});
}

async function ensureActiveTodo(state: MemoryState, title: string): Promise<string> {
	if (state.activeTodoPath && await exists(state.activeTodoPath)) return state.activeTodoPath;
	if (await exists(state.paths.sessionTodoPath)) return state.paths.sessionTodoPath;
	await mutateFileIfUnchanged(state.paths.sessionTodoPath, state.hashes.sessionTodo, () => createSessionTodoMarkdown(state, title));
	return state.paths.sessionTodoPath;
}

function sessionIdentity(ctx: ExtensionContext): MemorySessionIdentity {
	const header = ctx.sessionManager.getHeader() as { parentSession?: unknown } | null;
	const sessionFile = ctx.sessionManager.getSessionFile() || undefined;
	const rawSessionId = ctx.sessionManager.getSessionId() || sessionFile || undefined;
	const sessionName = ctx.sessionManager.getSessionName() || undefined;
	const id = rawSessionId ?? EPHEMERAL_SESSION_ID;
	const parentSession = typeof header?.parentSession === "string" ? header.parentSession : undefined;
	const explicitSubagent = Boolean(parentSession) || process.env.PI_SUBAGENT_CHILD === "1" || /^subagent[-_]/i.test(sessionName ?? "") || /\/run-\d+\/session\.jsonl$/.test(sessionFile ?? "");
	return {
		id,
		safeId: sanitizePathSegment(id, "session"),
		displayName: sessionName,
		sessionFile,
		parentSession,
		actorKind: explicitSubagent ? "subagent" : rawSessionId ? "owner" : "unknown",
		memoryMode: explicitSubagent || !rawSessionId ? "readonly" : "owner",
	};
}

async function recentMemoryEvents(paths: MemoryPaths): Promise<MemoryEventSummary[]> {
	const files = await recentMarkdownFiles(paths.eventsDir, RECENT_EVENT_LIMIT);
	const events: MemoryEventSummary[] = [];
	for (const file of files) {
		const content = await readOptional(file.path);
		const metadata = content ? parseMemoryEventMetadata(content) : undefined;
		const summary = extractSection(content, "Summary")?.replace(/\s+/g, " ").trim();
		events.push({ path: file.path, mtimeMs: file.mtimeMs, kind: metadata?.kind ?? "event", sessionId: metadata?.sessionId, summary });
	}
	return events;
}

async function recentSessionSummaries(paths: MemoryPaths): Promise<SessionProgressSummary[]> {
	const files = await recentSessionProgressFiles(paths, DASHBOARD_SESSION_LIMIT);
	const summaries: SessionProgressSummary[] = [];
	for (const file of files) {
		const content = await readOptional(file.path);
		if (!content) continue;
		const title = content.split(/\r?\n/, 1)[0]?.replace(/^#\s*/, "").trim() || file.sessionSafeId;
		const resume = extractSection(content, "Resume Here")?.replace(/\s+/g, " ").trim();
		summaries.push({ ...file, title, resume });
	}
	return summaries;
}

async function recentEventSnapshots(state: MemoryState): Promise<Array<{ path: string; content: string }>> {
	const snapshots: Array<{ path: string; content: string }> = [];
	for (const event of state.recentEvents.slice(0, DREAM_EVENT_SNAPSHOT_LIMIT)) {
		const content = await readOptional(event.path);
		if (content) snapshots.push({ path: relativeFrom(state.paths.projectDir, event.path), content });
	}
	return snapshots;
}

async function recentDigestSnapshots(state: MemoryState): Promise<Array<{ path: string; content: string }>> {
	try {
		const files = (await readdir(state.paths.eventDigestsDir))
			.filter((entry) => entry.endsWith(".md"))
			.sort((a, b) => b.localeCompare(a))
			.slice(0, DREAM_DIGEST_LIMIT);
		const snapshots: Array<{ path: string; content: string }> = [];
		for (const file of files) {
			const path = join(state.paths.eventDigestsDir, file);
			const content = await readOptional(path);
			if (content) snapshots.push({ path: relativeFrom(state.paths.projectDir, path), content });
		}
		return snapshots;
	} catch (error) {
		if (isNodeErrorCode(error, "ENOENT")) return [];
		throw error;
	}
}

function dreamSources(state: MemoryState, events: Array<{ path: string; content: string }>, digests: Array<{ path: string; content: string }>, todos: Array<{ path: string; content: string }>): MemorySource[] {
	const sources: MemorySource[] = [];
	if (state.progress) sources.push({ kind: "session-progress", path: relativeFrom(state.paths.projectDir, state.paths.sessionProgressPath), content: state.progress });
	if (state.projectMemory) sources.push({ kind: "memory", path: relativeFrom(state.paths.projectDir, state.paths.memoryPath), content: state.projectMemory });
	if (state.activeTodo) sources.push({ kind: "session-todo", path: relativeFrom(state.paths.projectDir, state.paths.sessionTodoPath), content: state.activeTodo });
	for (const event of events) sources.push({ kind: "event", path: event.path, content: event.content, event: parseMemoryEventMetadata(event.content) });
	for (const digest of digests) sources.push({ kind: "event-digest", path: digest.path, content: digest.content, event: parseMemoryEventMetadata(digest.content) });
	for (const todo of todos) sources.push({ kind: "legacy-todo", path: todo.path, content: todo.content });
	return sources;
}

function dreamSourceHashes(state: MemoryState, events: Array<{ path: string; content: string }>, digests: Array<{ path: string; content: string }>, todos: Array<{ path: string; content: string }>): Array<{ path: string; hash: string }> {
	return [
		{ path: relativeFrom(state.paths.projectDir, state.paths.sessionProgressPath), hash: sourceHashValue(state.hashes.sessionProgress) },
		{ path: relativeFrom(state.paths.projectDir, state.paths.sessionTodoPath), hash: sourceHashValue(state.hashes.sessionTodo) },
		{ path: relativeFrom(state.paths.projectDir, state.paths.progressPath), hash: sourceHashValue(state.hashes.dashboard) },
		{ path: relativeFrom(state.paths.projectDir, state.paths.memoryPath), hash: sourceHashValue(state.hashes.memory) },
		...events.map((event) => ({ path: event.path, hash: hashContent(event.content) })),
		...digests.map((digest) => ({ path: digest.path, hash: hashContent(digest.content) })),
		...todos.map((todo) => ({ path: todo.path, hash: hashContent(todo.content) })),
	];
}

function formatSourceList(sources: MemorySource[]): string {
	return sources.length ? sources.map((source) => `- ${source.path} (${source.kind})`).join("\n") : "None.";
}

function formatDreamEntries(entries: DreamMemoryEntryResult[], empty: string): string {
	return entries.length ? entries.map((entry) => `- [${entry.id}] ${entry.text} (${entry.reason ? `deferred: ${entry.reason}; ` : ""}ref: ${entry.ref}; source: ${entry.sources.join(", ")})`).join("\n") : empty;
}

function uniqueRefs(refs: string[]): string[] {
	return [...new Set(refs)];
}

function renderDashboard(state: MemoryState): string {
	const now = new Date();
	const sessions = state.recentSessions.length ? state.recentSessions : state.progress ? [{
		sessionSafeId: state.session.safeId,
		path: state.paths.sessionProgressPath,
		mtimeMs: Date.now(),
		title: `Progress: ${state.session.displayName ?? state.session.safeId}`,
		resume: extractSection(state.progress, "Resume Here")?.replace(/\s+/g, " ").trim(),
	}] : [];
	return `${MEMORY_LAYOUT_MARKER}
# Progress Dashboard

Generated by pi-memory-workbench. This shared \`progress.md\` is non-authoritative and is not the Resume Here source. Authoritative session state lives in \`sessions/\`.

## Current Session
- Session ID: ${state.session.id}
- Session progress: ${relativeFrom(state.paths.projectDir, state.paths.sessionProgressPath)}${state.progress ? "" : " (missing)"}
- Session todo: ${relativeFrom(state.paths.projectDir, state.paths.sessionTodoPath)}${state.activeTodo ? "" : " (missing)"}

## Sessions
${sessions.length ? sessions.map((session) => {
		const ageHours = Math.round((now.getTime() - session.mtimeMs) / 3_600_000);
		const status = ageHours <= DASHBOARD_ACTIVE_HOURS ? "active" : ageHours <= DASHBOARD_RECENT_HOURS ? "recent" : "stale";
		return `- ${status}: \`${session.sessionSafeId}\` — ${relativeFrom(state.paths.projectDir, session.path)}${session.resume ? ` — ${clip(session.resume, 180)}` : ""}`;
	}).join("\n") : "No session progress files found."}

## Recent Events
${state.recentEvents.length ? state.recentEvents.slice(0, 10).map((event) => `- ${event.kind}: ${relativeFrom(state.paths.projectDir, event.path)}${event.summary ? ` — ${clip(event.summary, 160)}` : ""}`).join("\n") : "No memory events found."}
`;
}

function defaultSessionProgress(state: MemoryState, seed: Partial<{ objective: string; currentState: string; nextAction: string; activeFiles: string[]; blockers: string; lastVerifiedCommand: string }> = {}): string {
	return `# Progress: ${state.session.displayName ?? state.session.safeId}

Session ID: ${state.session.id}
Session file: ${state.session.sessionFile ?? "None."}
Parent session: ${state.session.parentSession ?? "None."}
Project: ${state.paths.projectKey}
Last updated: ${new Date().toISOString()}
Status: active

${resumeSection(state, {
		objective: seed.objective ?? "Not recorded.",
		currentState: seed.currentState ?? "Not recorded.",
		nextAction: seed.nextAction ?? "Not recorded.",
		activeFiles: seed.activeFiles,
		blockers: seed.blockers ?? "None.",
		lastVerifiedCommand: seed.lastVerifiedCommand ?? "Not recorded.",
	})}

## Updates
`;
}

function updateSessionMetadata(content: string, state: MemoryState): string {
	if (!content.trim()) return defaultSessionProgress(state);
	const lines = content.split(/\r?\n/);
	const updates = new Map([
		["Session ID", state.session.id],
		["Session file", state.session.sessionFile ?? "None."],
		["Parent session", state.session.parentSession ?? "None."],
		["Project", state.paths.projectKey],
		["Last updated", new Date().toISOString()],
		["Status", "active"],
	]);
	for (const [label, value] of updates) {
		const index = lines.findIndex((line) => line.startsWith(`${label}:`));
		if (index >= 0) lines[index] = `${label}: ${value}`;
	}
	return lines.join("\n");
}

function resumeSection(state: MemoryState, params: {
	objective: string;
	currentState: string;
	nextAction: string;
	activeFiles?: string[];
	blockers?: string;
	lastVerifiedCommand?: string;
}): string {
	const activeFiles = params.activeFiles?.length ? params.activeFiles.map((file) => sanitizeProgressScalar(file, "Unnamed file.")).join(", ") : "None recorded.";
	const blockers = sanitizeProgressScalar(params.blockers, "None.");
	const lastVerified = sanitizeProgressScalar(params.lastVerifiedCommand, "Not recorded.");
	const activeTodo = state.activeTodoPath ?? (state.activeTodo ? state.paths.sessionTodoPath : "None.");
	return `## Resume Here
- Current objective: ${sanitizeProgressScalar(params.objective, "Not recorded.")}
- Current state: ${sanitizeProgressScalar(params.currentState, "Not recorded.")}
- Next action: ${sanitizeProgressScalar(params.nextAction, "Not recorded.")}
- Active todo file: ${activeTodo}
- Active files: ${activeFiles}
- Blockers/open questions: ${blockers}
- Last verified command: ${lastVerified}
`;
}

function createSessionTodoMarkdown(state: MemoryState, title: string): string {
	const base = createTodoMarkdown(title);
	return base.replace(/^#(.+)$/m, `#$1\n\nSession ID: ${state.session.id}\nSession progress: ${state.paths.sessionProgressPath}`);
}

async function writeMemoryEvent(state: MemoryState, kind: string, body: string): Promise<string> {
	const sessionProgress = relativeFrom(state.paths.projectDir, state.paths.sessionProgressPath);
	const sessionTodo = relativeFrom(state.paths.projectDir, state.paths.sessionTodoPath);
	const dashboard = relativeFrom(state.paths.projectDir, state.paths.progressPath);
	const memory = relativeFrom(state.paths.projectDir, state.paths.memoryPath);
	const metadata = formatMemoryEventMetadataV1({
		kind,
		created: new Date().toISOString(),
		sessionId: state.session.id,
		actorKind: state.session.actorKind,
		parentSession: state.session.parentSession,
		project: state.paths.projectKey,
		sessionProgress,
		sessionTodo,
		memory: state.hashes.memory.exists ? memory : `${memory} (missing)`,
		sourceHashes: [
			{ path: sessionProgress, hash: sourceHashValue(state.hashes.sessionProgress) },
			{ path: sessionTodo, hash: sourceHashValue(state.hashes.sessionTodo) },
			{ path: dashboard, hash: sourceHashValue(state.hashes.dashboard) },
			{ path: memory, hash: sourceHashValue(state.hashes.memory) },
		],
		relatedEvents: await findRelatedMemoryEvents(state.paths, { kind, sessionId: state.session.id }),
	});
	const content = `# Memory Event

${metadata}

${body.trim()}
`;
	return writeMemoryEventFile(state.paths, state.session.safeId, kind, content);
}

function sourceHashValue(snapshot: FileSnapshot): string {
	return snapshot.hash ?? (snapshot.exists ? "unknown" : "missing");
}

function checkpointEventBody(params: {
	objective: string;
	currentState: string;
	nextAction: string;
	activeFiles?: string[];
	blockers?: string;
	lastVerifiedCommand?: string;
	update?: string;
}): string {
	return `## Summary
${sanitizeProgressScalar(params.update, "Session checkpoint updated.")}

## Objective
${sanitizeProgressScalar(params.objective, "Not recorded.")}

## Current State
${sanitizeProgressScalar(params.currentState, "Not recorded.")}

## Next Action
${sanitizeProgressScalar(params.nextAction, "Not recorded.")}`;
}

async function readLegacyActiveTodo(state: MemoryState): Promise<{ path?: string; content?: string; error?: string } | undefined> {
	if (!state.currentTodo?.trim()) return undefined;
	try {
		const pointer = activeTodoPointer(state.currentTodo);
		const path = pointer ? resolveTodoPointer(state.paths, pointer) : state.paths.currentTodoPath;
		return { path, content: await readOptional(path) };
	} catch (error) {
		return { error: error instanceof Error ? error.message : String(error) };
	}
}

function withSessionTodoMetadata(state: MemoryState, content: string): string {
	const lines = content.trimEnd().split(/\r?\n/);
	const titleIndex = lines.findIndex((line) => line.startsWith("# "));
	if (titleIndex < 0) return createSessionTodoMarkdown(state, "Imported legacy todo");
	const filtered = lines.filter((line) => !line.startsWith("Session ID:") && !line.startsWith("Session progress:"));
	filtered.splice(titleIndex + 1, 0, "", `Session ID: ${state.session.id}`, `Session progress: ${state.paths.sessionProgressPath}`);
	return `${filtered.join("\n")}\n`;
}

function activeTodoPointer(content: string): string | undefined {
	const trimmed = content.trim();
	const match = trimmed.match(/^Active todo:\s*(.+)$/im);
	if (match?.[1]) return match[1].trim();
	return /^(?:\/|\.\/|\.\.\/)/.test(trimmed) || /^[^\r\n]+\.md$/.test(trimmed) ? trimmed.split(/\r?\n/, 1)[0]?.trim() : undefined;
}

async function recentTodoSummaries(state: MemoryState): Promise<Array<{ path: string; content: string }>> {
	const files = await recentMarkdownFiles(state.paths.todosDir, 5, { exclude: ["current.md"] });
	const summaries: Array<{ path: string; content: string }> = [];
	for (const file of files) {
		const content = await readOptional(file.path);
		if (content) summaries.push({ path: relativeFrom(state.paths.projectDir, file.path), content });
	}
	return summaries;
}

function replaceSection(content: string, heading: string, replacement: string): string {
	const pattern = new RegExp(`^##\\s+${escapeRegex(heading)}\\s*$`, "im");
	const match = pattern.exec(content);
	if (!match) return `${replacement.trimEnd()}\n\n${content.trimStart()}`;
	const start = match.index;
	const restStart = start + match[0].length;
	const rest = content.slice(restStart);
	const next = rest.search(/^##\s+/m);
	const end = next >= 0 ? restStart + next : content.length;
	return `${content.slice(0, start).trimEnd()}\n\n${replacement.trimEnd()}\n\n${content.slice(end).trimStart()}`.trimStart();
}

function appendUpdate(content: string, update: string): string {
	const line = `- ${new Date().toISOString().slice(0, 10)}: ${sanitizeProgressScalar(update, "Not recorded.")}`;
	if (/^##\s+Updates\s*$/im.test(content)) return content.replace(/(^##\s+Updates\s*$)/im, `$1\n${line}`);
	return `${content.trimEnd()}\n\n## Updates\n${line}\n`;
}

function appendNote(content: string, note: string): string {
	const line = `- ${note}`;
	if (/^##\s+Notes\s*$/im.test(content)) return content.replace(/(^##\s+Notes\s*$)/im, `$1\n${line}`);
	return `${content.trimEnd()}\n\n## Notes\n${line}\n`;
}

function appendTodoCheckpoint(content: string, update: string): string {
	const timestamp = new Date().toISOString().slice(0, 16).replace("T", " ");
	const safeUpdate = update
		.trim()
		.split(/\r?\n/)
		.map((line) => line.replace(/^(\s{0,3})##(\s+)/, "$1###$2").replace(/^(\s*[-*+]\s*)(?:TODO|DOING|DONE|BLOCKED)\s*:?\s+/i, "$1Checkpoint note: "))
		.join("\n");
	const block = `### Compaction checkpoint ${timestamp}\n${safeUpdate}`;
	if (/^##\s+Notes\s*$/im.test(content)) return content.replace(/(^##\s+Notes\s*$)/im, `$1\n${block}`);
	return `${content.trimEnd()}\n\n## Notes\n${block}\n`;
}

function taggedValue(content: string, tag: string): string | undefined {
	const match = new RegExp(`<${escapeRegex(tag)}\\b[^>]*>([\\s\\S]*?)<\\/${escapeRegex(tag)}>`, "i").exec(content);
	return match?.[1]?.trim() || undefined;
}

function isCopiedTemplatePlaceholder(value: string | undefined): boolean {
	if (!value) return false;
	const candidates = value
		.split(/\r?\n/)
		.map((line) => line.replace(/^\s*[-*]\s*/, "").replace(/\s+/g, " ").trim())
		.filter(Boolean);
	return candidates.some((candidate) => /^\[[^\]]+\]$/.test(candidate)
		|| /^Current objective in one sentence\.?$/i.test(candidate)
		|| /^Current state in one sentence\.?$/i.test(candidate)
		|| /^Exact next action in one sentence\.?$/i.test(candidate)
		|| /^None, or the open blocker\/question\.?$/i.test(candidate)
		|| /^Most recent verification command and result, or Not recorded\.?$/i.test(candidate)
		|| /^One concise chronological update for progress\.md\.?$/i.test(candidate)
		|| /^Short active todo title, only if a todo must be created\.?$/i.test(candidate)
		|| /\bpath\/or\/file\.ts\b/.test(candidate)
		|| /\banother\/path\.md\b/.test(candidate)
		|| /^Plain markdown prose to append under the active todo Notes section\./i.test(candidate)
		|| /^Markdown to append under the active todo Notes section\./i.test(candidate));
}

function isEmptyActiveFilesTemplate(value: string): boolean {
	const lines = value.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
	return lines.length > 0 && lines.every((line) => /^[-*+]\s*$/.test(line));
}

function hasUnsafeCheckpointScalar(value: string | undefined): boolean {
	if (!value) return false;
	return /<\/?[a-z][\s\S]*?>/i.test(value)
		|| /^\s{0,3}#{1,6}\s+/m.test(value)
		|| /^\s*[-*+]\s*(?:TODO|DOING|DONE|BLOCKED)\s*:?\s+/im.test(value);
}

function sanitizeProgressScalar(value: string | undefined, fallback: string): string {
	const sanitized = (value ?? "")
		.replace(/<\/?[a-z][^>]*>/gi, "")
		.split(/\r?\n/)
		.map((line) => line
			.replace(/^\s{0,3}#{1,6}\s+/, "")
			.replace(/^\s*[-*+]\s*(?:TODO|DOING|DONE|BLOCKED)\s*:?\s+/i, "")
			.trim())
		.filter(Boolean)
		.join(" ")
		.replace(/\s+/g, " ")
		.trim();
	return sanitized || fallback;
}

function parseActiveFiles(value: string | undefined): string[] {
	if (!value) return [];
	return value
		.split(/\r?\n|,/)
		.map((line) => line.replace(/^\s*[-*+]\s*/, "").trim())
		.filter((line) => line && !/^\(?none\.?\)?$/i.test(line));
}

function clip(value: string, max: number): string {
	return value.length > max ? `${value.slice(0, max - 20).trimEnd()}\n... [truncated]` : value;
}

function isNodeErrorCode(error: unknown, code: string): boolean {
	return Boolean(error && typeof error === "object" && "code" in error && error.code === code);
}

function escapeRegex(value: string): string {
	return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

export function widgetLines(state: MemoryState): string[] {
	const lines = [`memory: ${state.paths.projectKey} | dream: ${formatDreamStatus(state.dream)}`];
	if (state.parsedTodo) {
		lines.push(`task: ${state.parsedTodo.title}`);
		if (state.activeTodoPath) lines.push(`todo: ${relativeFrom(state.paths.projectDir, state.activeTodoPath)}`);
		const doing = state.parsedTodo.items.find((item) => item.status === "doing");
		if (doing) lines.push(`doing: ${doing.text}`);
		for (const item of state.parsedTodo.items.filter((item) => item.status === "todo" || item.status === "blocked").slice(0, 3)) {
			lines.push(`${item.status}: ${item.text}`);
		}
	} else {
		const currentFocus = extractSection(state.progress, "Current Focus") || extractSection(state.progress, "Resume Here");
		lines.push(currentFocus ? `progress: ${clip(currentFocus.replace(/\s+/g, " "), 120)}` : "no active todo");
	}
	return lines.slice(0, 7);
}

