import { readdir, realpath, stat } from "node:fs/promises";
import { basename, join, relative, resolve } from "node:path";
import { parseMemoryEventMetadata } from "./memory-events.ts";
import { readOptional, relativeFrom, type MemoryPaths } from "./paths.ts";
import type { MemoryState } from "./memory.ts";

export const MEMORY_RECALL_SCOPES = ["project", "session", "memory", "events", "dreams", "digests"] as const;
export type MemoryRecallScope = typeof MEMORY_RECALL_SCOPES[number];

export interface MemoryRecallOptions {
	query: string;
	scope?: MemoryRecallScope;
	sessionId?: string;
	kind?: string;
	limit?: number;
}

export interface MemoryRecallDocument {
	path: string;
	kind: string;
	content: string;
	title: string;
	sessionId?: string;
	created?: string;
}

export interface MemoryRecallHit {
	path: string;
	kind: string;
	title: string;
	sessionId?: string;
	created?: string;
	score: number;
	matchedTerms: string[];
	snippet: string;
}

export interface MemoryRecallResult {
	query: string;
	scope: MemoryRecallScope;
	totalDocuments: number;
	totalMatches: number;
	hits: MemoryRecallHit[];
}

const DEFAULT_LIMIT = 8;
const MAX_LIMIT = 20;
const MAX_QUERY_LENGTH = 256;
const MAX_EXPANDED_CHARS = 30_000;
const SNIPPET_CONTEXT_LINES = 1;
const STOPWORDS = new Set([
	"a", "an", "and", "are", "as", "at", "be", "been", "by", "did", "do", "does", "for", "from",
	"had", "has", "have", "how", "in", "is", "it", "its", "of", "on", "or", "that", "the", "their",
	"this", "to", "was", "were", "what", "when", "where", "which", "with",
]);

export async function recallMemory(state: MemoryState, options: MemoryRecallOptions, signal?: AbortSignal): Promise<MemoryRecallResult> {
	const query = options.query.trim();
	if (!query) throw new Error("memory_recall requires a non-empty query or path");
	if (query.length > MAX_QUERY_LENGTH) throw new Error(`memory_recall query must be at most ${MAX_QUERY_LENGTH} characters`);
	const scope = options.scope ?? "project";
	const limit = options.limit ?? DEFAULT_LIMIT;
	if (!Number.isInteger(limit) || limit < 1 || limit > MAX_LIMIT) throw new Error(`memory_recall limit must be an integer from 1 to ${MAX_LIMIT}`);
	throwIfAborted(signal);

	const documents = (await collectMemoryRecallDocuments(state, scope, signal)).filter((document) => {
		if (options.sessionId && document.sessionId !== options.sessionId) return false;
		if (options.kind && document.kind !== options.kind) return false;
		return true;
	});
	const terms = queryTerms(query);
	const stats = corpusStats(documents, terms);
	const scored = documents.map((document) => scoreDocument(document, query, terms, stats))
		.filter((result): result is { document: MemoryRecallDocument; score: number; matchedTerms: string[] } => Boolean(result))
		.sort((left, right) => right.score - left.score || left.document.path.localeCompare(right.document.path));

	return {
		query,
		scope,
		totalDocuments: documents.length,
		totalMatches: scored.length,
		hits: scored.slice(0, limit).map(({ document, score, matchedTerms }) => ({
			path: document.path,
			kind: document.kind,
			title: document.title,
			sessionId: document.sessionId,
			created: document.created,
			score: Number(score.toFixed(3)),
			matchedTerms,
			snippet: memorySnippet(document.content, terms),
		})),
	};
}

export async function expandMemorySource(state: MemoryState, requestedPath: string, signal?: AbortSignal): Promise<{ path: string; content: string; truncated: boolean }> {
	const path = requestedPath.trim().replace(/^@/, "");
	if (!path) throw new Error("memory_recall path must not be empty");
	const resolved = resolve(state.paths.projectDir, path);
	const projectRelative = relative(state.paths.projectDir, resolved);
	if (!projectRelative || projectRelative.startsWith("..") || projectRelative.startsWith("/")) {
		throw new Error("memory_recall path must stay inside the current project memory directory");
	}
	throwIfAborted(signal);
	const documents = await collectMemoryRecallDocuments(state, "project", signal);
	const document = documents.find((candidate) => candidate.path === projectRelative);
	if (!document) throw new Error(`memory_recall source is not a searchable workbench artifact: ${path}`);
	const truncated = document.content.length > MAX_EXPANDED_CHARS;
	return {
		path: document.path,
		content: truncated ? `${document.content.slice(0, MAX_EXPANDED_CHARS).trimEnd()}\n\n... [truncated; read ${document.path} directly for the remainder]\n` : document.content,
		truncated,
	};
}

export function formatMemoryRecall(result: MemoryRecallResult): string {
	if (!result.hits.length) return `No memory matches for "${result.query}" in scope ${result.scope} (${result.totalDocuments} sources searched).`;
	const header = `Memory recall: ${result.totalMatches} match${result.totalMatches === 1 ? "" : "es"} for "${result.query}" in scope ${result.scope} (${result.totalDocuments} sources searched; showing ${result.hits.length}).`;
	const hits = result.hits.map((hit, index) => {
		const metadata = [hit.kind, hit.sessionId ? `session ${hit.sessionId}` : undefined, hit.created].filter(Boolean).join(" | ");
		return `[${index + 1}] ${hit.path}\n${metadata}\n${hit.snippet}`;
	});
	return `${header}\n\n${hits.join("\n\n")}\n\nUse memory_recall with path set to an exact result path to expand its authoritative source.`;
}

export async function collectMemoryRecallDocuments(state: MemoryState, scope: MemoryRecallScope, signal?: AbortSignal): Promise<MemoryRecallDocument[]> {
	const documents: MemoryRecallDocument[] = [];
	if (scope === "project" || scope === "memory") await addSingleDocument(documents, state.paths, state.paths.memoryPath, "memory", signal);
	if (scope === "project" || scope === "session") {
		if (scope === "session") {
			await addSessionDocuments(documents, state.paths, state.session.safeId, signal, state.session.id);
		} else {
			for (const sessionId of await directoryNames(state.paths.sessionsDir)) await addSessionDocuments(documents, state.paths, sessionId, signal);
		}
	}
	if (scope === "project" || scope === "events" || scope === "session") {
		await addDirectoryDocuments(documents, state.paths, state.paths.eventsDir, "event", scope === "session" ? state.session.id : undefined, signal);
	}
	if (scope === "project" || scope === "dreams" || scope === "session") {
		await addDirectoryDocuments(documents, state.paths, state.paths.dreamsDir, "dream", scope === "session" ? state.session.id : undefined, signal, new Set(["last-run.md"]));
	}
	if (scope === "project" || scope === "digests") await addDirectoryDocuments(documents, state.paths, state.paths.eventDigestsDir, "event-digest", undefined, signal);
	return documents.sort((left, right) => left.path.localeCompare(right.path));
}

async function addSessionDocuments(documents: MemoryRecallDocument[], paths: MemoryPaths, sessionDirectory: string, signal?: AbortSignal, rawSessionId?: string): Promise<void> {
	await addSingleDocument(documents, paths, join(paths.sessionsDir, sessionDirectory, "progress.md"), "session-progress", signal, rawSessionId);
	await addSingleDocument(documents, paths, join(paths.sessionsDir, sessionDirectory, "todo.md"), "session-todo", signal, rawSessionId);
}

async function addDirectoryDocuments(documents: MemoryRecallDocument[], paths: MemoryPaths, directory: string, fallbackKind: string, sessionId: string | undefined, signal?: AbortSignal, excluded = new Set<string>()): Promise<void> {
	for (const name of await markdownFiles(directory)) {
		if (excluded.has(name)) continue;
		throwIfAborted(signal);
		const path = join(directory, name);
		const content = await readRecallDocument(paths, path);
		if (!content) continue;
		const metadata = parseMemoryEventMetadata(content);
		if (sessionId && metadata.sessionId !== sessionId) continue;
		documents.push(documentFromContent(paths, path, content, metadata.kind ?? fallbackKind, metadata.sessionId, metadata.created));
	}
}

async function addSingleDocument(documents: MemoryRecallDocument[], paths: MemoryPaths, path: string, kind: string, signal?: AbortSignal, sessionId?: string): Promise<void> {
	throwIfAborted(signal);
	const content = await readRecallDocument(paths, path);
	if (content) documents.push(documentFromContent(paths, path, content, kind, sessionId ?? sessionIdFromDocument(content)));
}

async function readRecallDocument(paths: MemoryPaths, path: string): Promise<string | undefined> {
	let projectRealPath: string;
	let documentRealPath: string;
	try {
		[projectRealPath, documentRealPath] = await Promise.all([realpath(paths.projectDir), realpath(path)]);
	} catch (error) {
		if (isNodeErrorCode(error, "ENOENT")) return undefined;
		throw error;
	}
	const resolvedRelative = relative(projectRealPath, documentRealPath);
	if (!resolvedRelative || resolvedRelative.startsWith("..") || resolvedRelative.startsWith("/")) {
		throw new Error(`Memory recall refused because ${relativeFrom(paths.projectDir, path)} resolves outside the project memory directory`);
	}
	return readOptional(documentRealPath);
}

function sessionIdFromDocument(content: string): string | undefined {
	const value = content.match(/^Session ID:\s*(.+)$/im)?.[1]?.trim();
	return value && !/^None\.?$/i.test(value) ? value : undefined;
}

function documentFromContent(paths: MemoryPaths, path: string, content: string, kind: string, sessionId?: string, created?: string): MemoryRecallDocument {
	return {
		path: relativeFrom(paths.projectDir, path),
		kind,
		content,
		title: content.match(/^#\s+(.+)$/m)?.[1]?.trim() ?? basename(path),
		sessionId,
		created,
	};
}

async function directoryNames(directory: string): Promise<string[]> {
	try {
		const names: string[] = [];
		for (const entry of await readdir(directory, { withFileTypes: true })) if (entry.isDirectory()) names.push(entry.name);
		return names.sort();
	} catch (error) {
		if (isNodeErrorCode(error, "ENOENT")) return [];
		throw error;
	}
}

async function markdownFiles(directory: string): Promise<string[]> {
	try {
		const files: string[] = [];
		for (const entry of await readdir(directory, { withFileTypes: true })) {
			if (!entry.isFile() || !entry.name.endsWith(".md")) continue;
			const info = await stat(join(directory, entry.name));
			if (info.isFile()) files.push(entry.name);
		}
		return files.sort();
	} catch (error) {
		if (isNodeErrorCode(error, "ENOENT")) return [];
		throw error;
	}
}

function queryTerms(query: string): string[] {
	const raw = query.toLowerCase().match(/[\p{L}\p{N}_.\/-]+/gu) ?? [];
	const meaningful = [...new Set(raw.filter((term) => term.length > 1 && !STOPWORDS.has(term)))];
	return meaningful.length ? meaningful : [...new Set(raw)];
}

function corpusStats(documents: MemoryRecallDocument[], terms: string[]): { documentCount: number; averageLength: number; documentFrequency: Map<string, number> } {
	const documentFrequency = new Map<string, number>();
	let totalLength = 0;
	for (const document of documents) {
		const text = searchableText(document);
		totalLength += tokenCount(text);
		for (const term of terms) if (text.includes(term)) documentFrequency.set(term, (documentFrequency.get(term) ?? 0) + 1);
	}
	return { documentCount: documents.length, averageLength: totalLength / Math.max(documents.length, 1), documentFrequency };
}

function scoreDocument(document: MemoryRecallDocument, query: string, terms: string[], stats: { documentCount: number; averageLength: number; documentFrequency: Map<string, number> }): { document: MemoryRecallDocument; score: number; matchedTerms: string[] } | undefined {
	const text = searchableText(document);
	const matchedTerms = terms.filter((term) => text.includes(term));
	if (!matchedTerms.length || (terms.length >= 2 && matchedTerms.length < 2)) return undefined;
	const length = tokenCount(text);
	let score = 0;
	for (const term of matchedTerms) {
		const frequency = occurrences(text, term);
		const documentFrequency = stats.documentFrequency.get(term) ?? 0;
		const inverseFrequency = Math.log((stats.documentCount - documentFrequency + 0.5) / (documentFrequency + 0.5) + 1);
		const saturation = (frequency * 2.2) / (frequency + 1.2 * (0.25 + 0.75 * length / Math.max(stats.averageLength, 1)));
		score += inverseFrequency * saturation;
		if (document.path.toLowerCase().includes(term)) score += 0.8;
	}
	if (text.includes(query.toLowerCase())) score += 2;
	return { document, score, matchedTerms };
}

function searchableText(document: MemoryRecallDocument): string {
	return `${document.path}\n${document.kind}\n${document.sessionId ?? ""}\n${document.title}\n${document.content}`.toLowerCase();
}

function tokenCount(text: string): number {
	return text.match(/[\p{L}\p{N}_.\/-]+/gu)?.length ?? 0;
}

function occurrences(text: string, term: string): number {
	let count = 0;
	let offset = 0;
	while ((offset = text.indexOf(term, offset)) >= 0) {
		count += 1;
		offset += term.length;
	}
	return count;
}

function memorySnippet(content: string, terms: string[]): string {
	const lines = content.split(/\r?\n/);
	const index = lines.findIndex((line) => terms.some((term) => line.toLowerCase().includes(term)));
	if (index < 0) return lines.slice(0, 3).join("\n").slice(0, 1_200);
	const start = Math.max(0, index - SNIPPET_CONTEXT_LINES);
	const end = Math.min(lines.length, index + SNIPPET_CONTEXT_LINES + 1);
	const snippet = [start > 0 ? `... (${start} lines above)` : undefined, ...lines.slice(start, end), end < lines.length ? `... (${lines.length - end} lines below)` : undefined]
		.filter((line): line is string => line !== undefined)
		.join("\n");
	return snippet.length > 1_200 ? `${snippet.slice(0, 1_180).trimEnd()}\n... [snippet truncated]` : snippet;
}

function throwIfAborted(signal?: AbortSignal): void {
	if (signal?.aborted) throw new Error("memory_recall aborted");
}

function isNodeErrorCode(error: unknown, code: string): boolean {
	return Boolean(error && typeof error === "object" && "code" in error && error.code === code);
}

