import { execFile } from "node:child_process";
import { createHash, randomBytes } from "node:crypto";
import { access, mkdir, readdir, readFile, stat, writeFile } from "node:fs/promises";
import { homedir } from "node:os";
import { basename, dirname, join, relative, resolve } from "node:path";
import { promisify } from "node:util";
import { withFileMutationQueue } from "@earendil-works/pi-coding-agent";

const execFileAsync = promisify(execFile);

export const MEMORY_LAYOUT_MARKER = "<!-- pi-memory-workbench-layout: session-events-v1 -->";

export type MemoryMode = "owner" | "readonly";

export interface MemorySessionIdentity {
	id: string;
	safeId: string;
	displayName?: string;
	sessionFile?: string;
	parentSession?: string;
	actorKind: "owner" | "subagent" | "unknown";
	memoryMode: MemoryMode;
}

export interface FileSnapshot {
	exists: boolean;
	hash: string | null;
}

export interface MemoryPaths {
	projectKey: string;
	projectDir: string;
	progressPath: string;
	memoryPath: string;
	sessionsDir: string;
	sessionDir: string;
	sessionProgressPath: string;
	sessionTodoPath: string;
	eventsDir: string;
	eventDigestsDir: string;
	todosDir: string;
	currentTodoPath: string;
	dreamsDir: string;
	lastRunPath: string;
	globalMemoryPath: string;
}

export async function resolveMemoryPaths(cwd: string, session: MemorySessionIdentity): Promise<MemoryPaths> {
	let root: string;
	try {
		const { stdout } = await execFileAsync("git", ["-C", cwd, "rev-parse", "--show-toplevel"]);
		root = stdout.trim() || cwd;
	} catch {
		// Git discovery is optional; any failure falls back to a cwd-based project key.
		root = cwd;
	}

	const projectKey = sanitizePathSegment(basename(root), "default");
	const memoryRoot = join(homedir(), ".pi", "agent", "memory");
	const projectDir = join(memoryRoot, projectKey);
	const sessionsDir = join(projectDir, "sessions");
	const sessionDir = join(sessionsDir, session.safeId);
	const todosDir = join(projectDir, "todos");
	const dreamsDir = join(projectDir, "dreams");
	const eventsDir = join(projectDir, "events");
	const eventDigestsDir = join(projectDir, "event-digests");

	return {
		projectKey,
		projectDir,
		progressPath: join(projectDir, "progress.md"),
		memoryPath: join(projectDir, "memory.md"),
		sessionsDir,
		sessionDir,
		sessionProgressPath: join(sessionDir, "progress.md"),
		sessionTodoPath: join(sessionDir, "todo.md"),
		eventsDir,
		eventDigestsDir,
		todosDir,
		currentTodoPath: join(todosDir, "current.md"),
		dreamsDir,
		lastRunPath: join(dreamsDir, "last-run.md"),
		globalMemoryPath: join(memoryRoot, "global.md"),
	};
}

export async function ensureMemoryDirs(paths: MemoryPaths): Promise<void> {
	await mkdir(paths.sessionDir, { recursive: true });
	await mkdir(paths.eventsDir, { recursive: true });
	await mkdir(paths.eventDigestsDir, { recursive: true });
	await mkdir(paths.todosDir, { recursive: true });
	await mkdir(paths.dreamsDir, { recursive: true });
}

export async function readOptional(path: string): Promise<string | undefined> {
	try {
		return await readFile(path, "utf8");
	} catch (error) {
		if (isNodeErrorCode(error, "ENOENT")) return undefined;
		throw error;
	}
}

export async function exists(path: string): Promise<boolean> {
	try {
		await access(path);
		return true;
	} catch (error) {
		if (isNodeErrorCode(error, "ENOENT")) return false;
		throw error;
	}
}

export async function fileSnapshot(path: string): Promise<FileSnapshot> {
	const content = await readOptional(path);
	return content === undefined ? { exists: false, hash: null } : { exists: true, hash: hashContent(content) };
}

export function hashContent(content: string): string {
	return `sha256:${createHash("sha256").update(content, "utf8").digest("hex")}`;
}

export async function mutateFile(path: string, update: (current: string) => string | Promise<string>): Promise<void> {
	await withFileMutationQueue(path, async () => {
		await mkdir(dirname(path), { recursive: true });
		const current = await readOptional(path) ?? "";
		await writeFile(path, await update(current), "utf8");
	});
}

export async function mutateFileIfUnchanged(path: string, expected: FileSnapshot | undefined, update: (current: string) => string | Promise<string>): Promise<void> {
	await withFileMutationQueue(path, async () => {
		await mkdir(dirname(path), { recursive: true });
		const current = await readOptional(path);
		const actual: FileSnapshot = current === undefined ? { exists: false, hash: null } : { exists: true, hash: hashContent(current) };
		if (expected && (actual.exists !== expected.exists || actual.hash !== expected.hash)) {
			throw new Error(`Memory conflict for ${path}: file changed since it was read. Re-read memory and retry.`);
		}
		await writeFile(path, await update(current ?? ""), "utf8");
	});
}

export async function writeNewFile(path: string, content: string): Promise<string> {
	for (let attempt = 1; attempt <= 100; attempt += 1) {
		const candidate = numberedPath(path, attempt);
		try {
			return await writeExclusiveFile(candidate, content);
		} catch (error) {
			if (isNodeErrorCode(error, "EEXIST")) continue;
			throw error;
		}
	}
	throw new Error(`Could not create a unique file for ${path}`);
}

export async function writeExclusiveFile(path: string, content: string): Promise<string> {
	await withFileMutationQueue(path, async () => {
		await mkdir(dirname(path), { recursive: true });
		await writeFile(path, content, { encoding: "utf8", flag: "wx" });
	});
	return path;
}

export async function writeMemoryEventFile(paths: MemoryPaths, sessionSafeId: string, kind: string, content: string): Promise<string> {
	const fileName = `${compactTimestamp()}-${sanitizePathSegment(sessionSafeId, "session")}-${sanitizePathSegment(kind, "event")}-${randomBytes(3).toString("hex")}.md`;
	return writeNewFile(join(paths.eventsDir, fileName), content);
}

export async function recentMarkdownFiles(dir: string, limit: number, options: { exclude?: string[] } = {}): Promise<Array<{ path: string; mtimeMs: number }>> {
	try {
		const excluded = new Set(options.exclude ?? []);
		const files: Array<{ path: string; mtimeMs: number }> = [];
		for (const entry of await readdir(dir)) {
			if (!entry.endsWith(".md") || excluded.has(entry)) continue;
			const fullPath = join(dir, entry);
			const info = await stat(fullPath);
			if (info.isFile()) files.push({ path: fullPath, mtimeMs: info.mtimeMs });
		}
		return files.sort((a, b) => b.mtimeMs - a.mtimeMs).slice(0, limit);
	} catch (error) {
		if (isNodeErrorCode(error, "ENOENT")) return [];
		throw error;
	}
}

export async function recentSessionProgressFiles(paths: MemoryPaths, limit: number): Promise<Array<{ sessionSafeId: string; path: string; mtimeMs: number }>> {
	try {
		const files: Array<{ sessionSafeId: string; path: string; mtimeMs: number }> = [];
		for (const entry of await readdir(paths.sessionsDir)) {
			const progressPath = join(paths.sessionsDir, entry, "progress.md");
			try {
				const info = await stat(progressPath);
				if (info.isFile()) files.push({ sessionSafeId: entry, path: progressPath, mtimeMs: info.mtimeMs });
			} catch (error) {
				if (!isNodeErrorCode(error, "ENOENT") && !isNodeErrorCode(error, "ENOTDIR")) throw error;
			}
		}
		return files.sort((a, b) => b.mtimeMs - a.mtimeMs).slice(0, limit);
	} catch (error) {
		if (isNodeErrorCode(error, "ENOENT")) return [];
		throw error;
	}
}

export function relativeFrom(baseDir: string, path: string): string {
	const value = relative(baseDir, path);
	return value && !value.startsWith("..") && !value.startsWith("/") ? value : path;
}

export function resolveTodoPointer(paths: MemoryPaths, pointer: string): string {
	const raw = pointer.replace(/^["']|["']$/g, "").trim();
	if (!raw) return paths.currentTodoPath;
	const resolved = resolve(paths.todosDir, raw);
	const value = relative(paths.todosDir, resolved);
	if (value.startsWith("..") || value.startsWith("/") || value === "") {
		throw new Error(`Active todo pointer must stay inside ${paths.todosDir}: ${raw}`);
	}
	return resolved;
}

export function sanitizePathSegment(value: string | undefined, fallback: string): string {
	const raw = (value ?? "").trim();
	const sanitized = raw.replace(/[^a-zA-Z0-9._-]+/g, "-").replace(/^-+|-+$/g, "");
	const base = sanitized || fallback;
	if (raw && sanitized === raw && sanitized.length <= 120) return sanitized;
	const hash = createHash("sha256").update(raw || fallback, "utf8").digest("hex").slice(0, 8);
	return `${base.slice(0, 111).replace(/-+$/g, "")}-${hash}`;
}

export function compactTimestamp(date = new Date()): string {
	return date.toISOString().replace(/[-:]/g, "").replace(/\.\d{3}Z$/, "Z");
}

function numberedPath(path: string, attempt: number): string {
	if (attempt === 1) return path;
	return path.endsWith(".md") ? `${path.slice(0, -3)}-${attempt}.md` : `${path}-${attempt}`;
}

function isNodeErrorCode(error: unknown, code: string): boolean {
	return Boolean(error && typeof error === "object" && "code" in error && error.code === code);
}

